// Máquinas Eléctricas - Estructura tipo T2 (por unidades + simulacro)
// A falta de preguntas oficiales reales de la plataforma, se usan preguntas
// elaboradas a partir de los PDFs U1-U13 del temario, marcadas como TEST OFICIAL.
// Cada unidad cuenta con un banco de 20 preguntas; el simulacro toma una selección de 40 preguntas.

const TEMA_MAQUINAS_U1_DATA = [
  { id: 800101, tema: "U1: Introducción al taller de máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué instrumento se utiliza para obtener medidas interiores, exteriores o de profundidad con precisión a la décima de milímetro?", opciones: ["El calibre o pie de rey", "El micrómetro o palmer", "El tacómetro", "El megóhmetro"], correctaTexto: "El calibre o pie de rey", explicacion: "El calibre o pie de rey permite obtener medidas interiores, exteriores o de profundidad con una precisión a la décima de milímetro." },
  { id: 800102, tema: "U1: Introducción al taller de máquinas eléctricas (TEST OFICIAL)", texto: "¿Hasta qué precisión permite medir el micrómetro o palmer?", opciones: ["La centésima de milímetro", "La décima de milímetro", "El milímetro entero", "El metro"], correctaTexto: "La centésima de milímetro", explicacion: "El micrómetro se utiliza cuando se requiere una medida aún más precisa que el calibre, llegando hasta la centésima de milímetro." },
  { id: 800103, tema: "U1: Introducción al taller de máquinas eléctricas (TEST OFICIAL)", texto: "¿Para qué se utiliza la estufa de secado en un taller de máquinas eléctricas?", opciones: ["Para secar rápidamente el barniz que se impregna en los bobinados", "Para calentar el taller en invierno", "Para fundir metales", "Para almacenar herramientas"], correctaTexto: "Para secar rápidamente el barniz que se impregna en los bobinados", explicacion: "La estufa de secado eleva la temperatura al punto necesario para que el barniz impregnado en los bobinados se seque rápidamente." },
  { id: 800104, tema: "U1: Introducción al taller de máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué máquina se utiliza para realizar los devanados eléctricos?", opciones: ["La bobinadora", "La cizalla", "La electroesmeriladora", "La taladradora"], correctaTexto: "La bobinadora", explicacion: "Las bobinadoras se aplican para realizar los devanados eléctricos y pueden ser manuales o automáticas." },
  { id: 800105, tema: "U1: Introducción al taller de máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué instrumento se utiliza para medir la velocidad de rotación de un motor?", opciones: ["El tacómetro", "El calibre", "El micrómetro", "El megóhmetro"], correctaTexto: "El tacómetro", explicacion: "El tacómetro es el instrumento empleado para medir la velocidad de rotación (revoluciones por minuto) del eje de un motor u otra máquina rotativa." },
  { id: 800106, tema: "U1: Introducción al taller de máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué herramienta se emplea en el taller para cortar chapas metálicas de forma manual?", opciones: ["La cizalla", "El calibre", "El tacómetro", "El megóhmetro"], correctaTexto: "La cizalla", explicacion: "La cizalla es la herramienta manual o mecánica empleada en el taller para el corte de chapas metálicas utilizadas en la construcción de máquinas eléctricas." },
  { id: 800107, tema: "U1: Introducción al taller de máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué equipo de protección individual es imprescindible al trabajar con la electroesmeriladora?", opciones: ["Gafas de protección ocular", "Guantes aislantes de alta tensión", "Casco con pantalla facial de soldador", "Botas de agua"], correctaTexto: "Gafas de protección ocular", explicacion: "Al utilizar la electroesmeriladora se generan partículas y chispas que pueden dañar los ojos, por lo que es imprescindible el uso de gafas de protección ocular." },
  { id: 800108, tema: "U1: Introducción al taller de máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué función cumple el banco de trabajo en un taller de máquinas eléctricas?", opciones: ["Servir de superficie de apoyo estable para el montaje y reparación de máquinas", "Almacenar exclusivamente productos químicos", "Sustituir a la bobinadora en el devanado", "Medir la resistencia de aislamiento"], correctaTexto: "Servir de superficie de apoyo estable para el montaje y reparación de máquinas", explicacion: "El banco de trabajo proporciona una superficie estable y resistente sobre la que realizar tareas de montaje, desmontaje y reparación de máquinas eléctricas." },
  { id: 800109, tema: "U1: Introducción al taller de máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué es el barniz de impregnación utilizado en los bobinados de las máquinas eléctricas?", opciones: ["Un producto aislante que protege el bobinado de la humedad y mejora su rigidez dieléctrica", "Un lubricante para los cojinetes del rotor", "Un producto exclusivamente decorativo", "Un disolvente para limpiar el núcleo magnético"], correctaTexto: "Un producto aislante que protege el bobinado de la humedad y mejora su rigidez dieléctrica", explicacion: "El barniz de impregnación es un producto aislante que, aplicado sobre el bobinado, lo protege frente a la humedad, mejora su rigidez dieléctrica y aumenta su resistencia mecánica." },
  { id: 800110, tema: "U1: Introducción al taller de máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué herramienta manual se utiliza para apretar o aflojar tornillos con cabeza ranurada?", opciones: ["El destornillador", "El calibre", "El polímetro", "El tacómetro"], correctaTexto: "El destornillador", explicacion: "El destornillador es la herramienta manual básica utilizada para apretar o aflojar tornillos con cabeza ranurada durante el montaje y desmontaje de máquinas." },
  { id: 800111, tema: "U1: Introducción al taller de máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué instrumento de medida eléctrica es imprescindible en cualquier taller de máquinas eléctricas para medir tensión, intensidad y resistencia?", opciones: ["El polímetro o multímetro", "El micrómetro", "La cizalla", "La estufa de secado"], correctaTexto: "El polímetro o multímetro", explicacion: "El polímetro o multímetro es el instrumento de medida eléctrica básico e imprescindible que permite medir tensión, intensidad y resistencia en un taller de máquinas eléctricas." },
  { id: 800112, tema: "U1: Introducción al taller de máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué máquina-herramienta se utiliza para realizar orificios precisos en piezas metálicas durante la reparación de máquinas eléctricas?", opciones: ["La taladradora", "La bobinadora", "La estufa de secado", "El megóhmetro"], correctaTexto: "La taladradora", explicacion: "La taladradora es la máquina-herramienta empleada para realizar orificios precisos en piezas metálicas, necesarios en muchas operaciones de montaje y reparación." },
  { id: 800113, tema: "U1: Introducción al taller de máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué es un extractor de rodamientos y para qué se utiliza?", opciones: ["Una herramienta mecánica que permite retirar rodamientos sin dañar el eje ni el propio rodamiento", "Un instrumento de medida de resistencia de aislamiento", "Un producto químico para limpiar bobinados", "Un tipo de sensor de temperatura"], correctaTexto: "Una herramienta mecánica que permite retirar rodamientos sin dañar el eje ni el propio rodamiento", explicacion: "El extractor de rodamientos es una herramienta mecánica diseñada para desmontar rodamientos de un eje de forma controlada, evitando dañar tanto el eje como el rodamiento." },
  { id: 800114, tema: "U1: Introducción al taller de máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué norma de seguridad básica debe respetarse siempre antes de manipular una máquina eléctrica en el taller?", opciones: ["Desconectar la alimentación eléctrica y verificar la ausencia de tensión", "Trabajar siempre con la máquina conectada para comprobar su funcionamiento", "Ignorar la desconexión si la reparación es rápida", "Usar herramientas metálicas sin ningún aislamiento"], correctaTexto: "Desconectar la alimentación eléctrica y verificar la ausencia de tensión", explicacion: "Antes de manipular cualquier máquina eléctrica es imprescindible desconectar su alimentación y verificar la ausencia de tensión, siguiendo las normas básicas de seguridad eléctrica." },
  { id: 800115, tema: "U1: Introducción al taller de máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué es una lima y para qué se emplea en el taller de máquinas eléctricas?", opciones: ["Una herramienta manual utilizada para desbastar o alisar superficies metálicas", "Un instrumento de medida de tensión eléctrica", "Un producto químico aislante", "Un tipo de rodamiento especial"], correctaTexto: "Una herramienta manual utilizada para desbastar o alisar superficies metálicas", explicacion: "La lima es una herramienta manual de corte utilizada para desbastar, alisar o ajustar superficies metálicas durante tareas de mecanizado en el taller." },
  { id: 800116, tema: "U1: Introducción al taller de máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué finalidad tiene el uso de plantillas de bobinado en la fabricación de devanados?", opciones: ["Garantizar que todas las bobinas tengan la forma y dimensiones exactas requeridas", "Medir la resistencia de aislamiento del bobinado", "Sustituir a la bobinadora en todo el proceso", "Detectar cortocircuitos entre espiras"], correctaTexto: "Garantizar que todas las bobinas tengan la forma y dimensiones exactas requeridas", explicacion: "Las plantillas de bobinado aseguran que todas las bobinas fabricadas tengan exactamente la misma forma y dimensiones, garantizando la uniformidad del devanado." },
  { id: 800117, tema: "U1: Introducción al taller de máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué tipo de hilo se utiliza habitualmente en el bobinado de máquinas eléctricas de pequeña potencia?", opciones: ["Hilo de cobre esmaltado", "Hilo de aluminio desnudo", "Hilo de acero galvanizado", "Hilo de fibra óptica"], correctaTexto: "Hilo de cobre esmaltado", explicacion: "El hilo de cobre esmaltado, recubierto con una fina capa aislante, es el conductor habitual utilizado en el bobinado de máquinas eléctricas de pequeña y mediana potencia." },
  { id: 800118, tema: "U1: Introducción al taller de máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué información proporciona la placa de características de una máquina eléctrica?", opciones: ["Datos técnicos como tensión, intensidad, potencia, frecuencia y velocidad nominal", "Solo el nombre del fabricante sin datos técnicos", "Únicamente el precio de la máquina", "Solo el color de la carcasa"], correctaTexto: "Datos técnicos como tensión, intensidad, potencia, frecuencia y velocidad nominal", explicacion: "La placa de características de una máquina eléctrica recoge los datos técnicos fundamentales: tensión, intensidad, potencia, frecuencia, velocidad nominal, entre otros." },
  { id: 800119, tema: "U1: Introducción al taller de máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué es la limpieza por aire comprimido y cuándo se recomienda su uso en el mantenimiento de máquinas eléctricas?", opciones: ["Un método para eliminar polvo y suciedad de los bobinados sin dañarlos, recomendado en el mantenimiento preventivo", "Un método exclusivo para pintar carcasas metálicas", "Un método para medir la resistencia de aislamiento", "Un método para soldar conexiones eléctricas"], correctaTexto: "Un método para eliminar polvo y suciedad de los bobinados sin dañarlos, recomendado en el mantenimiento preventivo", explicacion: "La limpieza por aire comprimido permite eliminar polvo y suciedad acumulados en los bobinados y otras partes de la máquina sin dañar los componentes, siendo habitual en el mantenimiento preventivo." },
  { id: 800120, tema: "U1: Introducción al taller de máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué precaución se debe tener al almacenar disolventes y barnices en el taller de máquinas eléctricas?", opciones: ["Almacenarlos en lugares ventilados, alejados de fuentes de calor o chispas, conforme a la normativa de seguridad", "Almacenarlos junto a cualquier fuente de calor sin ninguna precaución", "No es necesario adoptar ninguna medida especial", "Guardarlos en recipientes sin etiquetar"], correctaTexto: "Almacenarlos en lugares ventilados, alejados de fuentes de calor o chispas, conforme a la normativa de seguridad", explicacion: "Los disolventes y barnices son productos inflamables que deben almacenarse en lugares ventilados y alejados de fuentes de calor o chispas, cumpliendo la normativa de seguridad e higiene en el trabajo." }
];

const TEMA_MAQUINAS_U2_DATA = [
  { id: 800201, tema: "U2: Nociones de magnetismo (TEST OFICIAL)", texto: "¿Cómo se comportan dos imanes cuando se acercan polos de la misma orientación (Norte-Norte)?", opciones: ["Se repelen", "Se atraen", "No interaccionan", "Se anulan"], correctaTexto: "Se repelen", explicacion: "Dos imanes se repelerán si se acercan los polos con la misma orientación, es decir, Norte-Norte o Sur-Sur." },
  { id: 800202, tema: "U2: Nociones de magnetismo (TEST OFICIAL)", texto: "¿Cuál es la unidad de medida del flujo magnético en el Sistema Internacional?", opciones: ["El weber (Wb)", "El amperio (A)", "El ohmio (Ω)", "El vatio (W)"], correctaTexto: "El weber (Wb)", explicacion: "La unidad estándar para el flujo magnético es el weber (Wb), equivalente a un tesla por metro cuadrado." },
  { id: 800203, tema: "U2: Nociones de magnetismo (TEST OFICIAL)", texto: "¿Qué regla permite conocer el sentido de las líneas de fuerza de un conductor rectilíneo agarrándolo con la mano de forma que el pulgar indique el sentido de la corriente?", opciones: ["Regla de la mano derecha", "Regla de la mano izquierda", "Regla de Lenz", "Regla de Kirchhoff"], correctaTexto: "Regla de la mano derecha", explicacion: "Si con la mano derecha se agarra el conductor de manera que el pulgar indique el sentido de la corriente, el resto de los dedos indica el sentido de las líneas de fuerza." },
  { id: 800204, tema: "U2: Nociones de magnetismo (TEST OFICIAL)", texto: "¿Qué es la inducción magnética (B) y en qué unidad se mide?", opciones: ["La densidad de flujo magnético por unidad de superficie, medida en teslas (T)", "La fuerza mecánica ejercida por un imán, medida en newtons", "La velocidad de propagación de un campo magnético, medida en m/s", "La resistencia eléctrica de un material magnético, medida en ohmios"], correctaTexto: "La densidad de flujo magnético por unidad de superficie, medida en teslas (T)", explicacion: "La inducción magnética (B) es la densidad de flujo magnético por unidad de superficie, y su unidad en el Sistema Internacional es el tesla (T)." },
  { id: 800205, tema: "U2: Nociones de magnetismo (TEST OFICIAL)", texto: "¿Qué es un material ferromagnético?", opciones: ["Un material que se imanta fuertemente al someterse a un campo magnético, como el hierro", "Un material que repele completamente cualquier campo magnético", "Un material aislante eléctrico sin propiedades magnéticas", "Un material que solo conduce electricidad, sin propiedades magnéticas"], correctaTexto: "Un material que se imanta fuertemente al someterse a un campo magnético, como el hierro", explicacion: "Los materiales ferromagnéticos, como el hierro, el níquel o el cobalto, se imantan fuertemente al someterse a un campo magnético externo, siendo la base de los núcleos de las máquinas eléctricas." },
  { id: 800206, tema: "U2: Nociones de magnetismo (TEST OFICIAL)", texto: "¿Qué es el magnetismo remanente en un material ferromagnético?", opciones: ["El magnetismo que conserva el material tras eliminar el campo magnético externo que lo imantó", "El campo magnético total aplicado durante la imantación", "La resistencia eléctrica del material una vez desmagnetizado", "La temperatura a la que el material pierde sus propiedades magnéticas"], correctaTexto: "El magnetismo que conserva el material tras eliminar el campo magnético externo que lo imantó", explicacion: "El magnetismo remanente es el magnetismo que permanece en un material ferromagnético después de retirar el campo magnético externo que provocó su imantación." },
  { id: 800207, tema: "U2: Nociones de magnetismo (TEST OFICIAL)", texto: "¿Qué es la reluctancia magnética de un circuito?", opciones: ["La oposición que presenta un circuito al paso del flujo magnético", "La facilidad con que un circuito conduce la corriente eléctrica", "La capacidad de un material para almacenar carga eléctrica", "La velocidad de propagación de las líneas de fuerza"], correctaTexto: "La oposición que presenta un circuito al paso del flujo magnético", explicacion: "La reluctancia magnética es el equivalente magnético de la resistencia eléctrica: representa la oposición que ofrece un circuito magnético al paso del flujo." },
  { id: 800208, tema: "U2: Nociones de magnetismo (TEST OFICIAL)", texto: "¿Qué ley establece que la fuerza electromotriz inducida en un circuito es proporcional a la variación del flujo magnético que lo atraviesa?", opciones: ["Ley de Faraday", "Ley de Ohm", "Ley de Coulomb", "Ley de Joule"], correctaTexto: "Ley de Faraday", explicacion: "La Ley de Faraday de la inducción electromagnética establece que la fuerza electromotriz inducida en un circuito es proporcional a la rapidez de variación del flujo magnético que lo atraviesa." },
  { id: 800209, tema: "U2: Nociones de magnetismo (TEST OFICIAL)", texto: "¿Qué establece la Ley de Lenz respecto al sentido de la corriente inducida?", opciones: ["La corriente inducida tiene un sentido tal que se opone a la causa que la produce", "La corriente inducida siempre favorece la variación del flujo magnético", "La corriente inducida no tiene ningún sentido definido", "La corriente inducida solo aparece en corriente continua"], correctaTexto: "La corriente inducida tiene un sentido tal que se opone a la causa que la produce", explicacion: "La Ley de Lenz establece que el sentido de la corriente inducida es tal que se opone siempre a la causa que la produce, es decir, a la variación del flujo magnético." },
  { id: 800210, tema: "U2: Nociones de magnetismo (TEST OFICIAL)", texto: "¿Qué es un electroimán?", opciones: ["Un dispositivo que genera un campo magnético mediante el paso de corriente eléctrica por una bobina", "Un imán natural extraído directamente de un mineral", "Un dispositivo que convierte energía magnética directamente en calor", "Un tipo de resistencia eléctrica variable"], correctaTexto: "Un dispositivo que genera un campo magnético mediante el paso de corriente eléctrica por una bobina", explicacion: "Un electroimán es un dispositivo formado por una bobina, habitualmente arrollada sobre un núcleo ferromagnético, que genera un campo magnético al circular corriente eléctrica por ella." },
  { id: 800211, tema: "U2: Nociones de magnetismo (TEST OFICIAL)", texto: "¿Qué es el ciclo de histéresis de un material ferromagnético?", opciones: ["La representación gráfica de la relación entre la inducción magnética y el campo magnético aplicado durante un ciclo completo de imantación", "Una medida directa de la resistencia eléctrica del material", "Un fenómeno exclusivo de los materiales aislantes", "Un proceso de fabricación de imanes permanentes"], correctaTexto: "La representación gráfica de la relación entre la inducción magnética y el campo magnético aplicado durante un ciclo completo de imantación", explicacion: "El ciclo de histéresis representa gráficamente la relación entre la inducción magnética (B) y el campo magnético aplicado (H) durante un ciclo completo de magnetización y desmagnetización." },
  { id: 800212, tema: "U2: Nociones de magnetismo (TEST OFICIAL)", texto: "¿Qué son las pérdidas por histéresis en el núcleo de una máquina eléctrica?", opciones: ["La energía disipada en forma de calor al recorrer repetidamente el ciclo de imantación y desimantación", "Las pérdidas producidas exclusivamente en los bobinados por efecto Joule", "Las pérdidas debidas al rozamiento mecánico de los cojinetes", "Las pérdidas producidas por la resistencia del aire al giro del rotor"], correctaTexto: "La energía disipada en forma de calor al recorrer repetidamente el ciclo de imantación y desimantación", explicacion: "Las pérdidas por histéresis son la energía disipada en forma de calor cada vez que el material del núcleo recorre el ciclo de imantación y desimantación al trabajar con corriente alterna." },
  { id: 800213, tema: "U2: Nociones de magnetismo (TEST OFICIAL)", texto: "¿Qué son las corrientes de Foucault en el núcleo de una máquina eléctrica?", opciones: ["Corrientes parásitas inducidas en el núcleo metálico que generan pérdidas de energía en forma de calor", "Corrientes exclusivas del devanado inducido de las máquinas de corriente continua", "Corrientes que solo aparecen en circuitos de corriente continua pura", "Corrientes que mejoran el rendimiento del núcleo magnético"], correctaTexto: "Corrientes parásitas inducidas en el núcleo metálico que generan pérdidas de energía en forma de calor", explicacion: "Las corrientes de Foucault son corrientes parásitas inducidas en el material conductor del núcleo, que generan pérdidas de energía en forma de calor y reducen el rendimiento de la máquina." },
  { id: 800214, tema: "U2: Nociones de magnetismo (TEST OFICIAL)", texto: "¿Por qué se laminan los núcleos magnéticos de las máquinas eléctricas de corriente alterna?", opciones: ["Para reducir las pérdidas por corrientes de Foucault", "Para aumentar el peso total de la máquina", "Para mejorar exclusivamente el aspecto estético", "Para facilitar la conexión del bobinado inductor"], correctaTexto: "Para reducir las pérdidas por corrientes de Foucault", explicacion: "La laminación del núcleo en chapas finas aisladas entre sí reduce considerablemente las pérdidas por corrientes de Foucault, mejorando el rendimiento de la máquina." },
  { id: 800215, tema: "U2: Nociones de magnetismo (TEST OFICIAL)", texto: "¿Qué relación existe entre el campo magnético (H) y la inducción magnética (B) en un material?", opciones: ["B = µ·H, donde µ es la permeabilidad magnética del material", "B y H son magnitudes idénticas sin ninguna relación matemática", "H es siempre mayor que B en cualquier material", "No existe ninguna relación entre B y H"], correctaTexto: "B = µ·H, donde µ es la permeabilidad magnética del material", explicacion: "La relación entre la inducción magnética (B) y el campo magnético (H) viene dada por la permeabilidad magnética del material (µ), según la fórmula B = µ·H." },
  { id: 800216, tema: "U2: Nociones de magnetismo (TEST OFICIAL)", texto: "¿Qué es la permeabilidad magnética de un material?", opciones: ["La facilidad con que un material se deja atravesar por las líneas de campo magnético", "La resistencia eléctrica que ofrece el material al paso de la corriente", "La capacidad de un material para almacenar carga eléctrica", "La temperatura máxima que soporta un material antes de fundirse"], correctaTexto: "La facilidad con que un material se deja atravesar por las líneas de campo magnético", explicacion: "La permeabilidad magnética indica la facilidad con la que un material permite que lo atraviesen las líneas de campo magnético, siendo muy elevada en los materiales ferromagnéticos." },
  { id: 800217, tema: "U2: Nociones de magnetismo (TEST OFICIAL)", texto: "¿Qué es un campo magnético giratorio y en qué tipo de máquinas se genera?", opciones: ["Un campo magnético cuya dirección va rotando en el tiempo, generado en máquinas de corriente alterna polifásicas", "Un campo magnético estático que nunca varía su dirección", "Un fenómeno exclusivo de las máquinas de corriente continua", "Un campo que solo aparece en los transformadores monofásicos"], correctaTexto: "Un campo magnético cuya dirección va rotando en el tiempo, generado en máquinas de corriente alterna polifásicas", explicacion: "El campo magnético giratorio es un campo cuya dirección rota progresivamente en el tiempo, generado típicamente en los estatores de las máquinas de corriente alterna polifásicas (motores asíncronos, alternadores)." },
  { id: 800218, tema: "U2: Nociones de magnetismo (TEST OFICIAL)", texto: "¿Qué establece la regla de la mano izquierda (regla de Fleming) aplicada a motores?", opciones: ["Permite determinar el sentido de la fuerza que actúa sobre un conductor recorrido por corriente dentro de un campo magnético", "Solo se aplica para determinar el sentido de la corriente inducida en generadores", "Es equivalente a la Ley de Ohm aplicada a circuitos magnéticos", "Determina exclusivamente la polaridad de una pila"], correctaTexto: "Permite determinar el sentido de la fuerza que actúa sobre un conductor recorrido por corriente dentro de un campo magnético", explicacion: "La regla de la mano izquierda o regla de Fleming para motores permite determinar el sentido de la fuerza mecánica que actúa sobre un conductor recorrido por corriente situado dentro de un campo magnético." },
  { id: 800219, tema: "U2: Nociones de magnetismo (TEST OFICIAL)", texto: "¿Qué unidad del Sistema Internacional mide la intensidad de campo magnético (H)?", opciones: ["Amperio-vuelta por metro (A/m)", "Tesla (T)", "Weber (Wb)", "Henrio (H)"], correctaTexto: "Amperio-vuelta por metro (A/m)", explicacion: "La intensidad de campo magnético (H) se mide en el Sistema Internacional en amperios-vuelta por metro (A/m), diferenciándose de la inducción magnética (B), que se mide en teslas." },
  { id: 800220, tema: "U2: Nociones de magnetismo (TEST OFICIAL)", texto: "¿Qué es la fuerza magnetomotriz (f.m.m.) de una bobina?", opciones: ["El producto entre el número de espiras de la bobina y la intensidad de corriente que circula por ella", "La fuerza mecánica que ejerce el imán sobre un objeto metálico", "La resistencia eléctrica total de la bobina", "La velocidad angular del campo magnético generado"], correctaTexto: "El producto entre el número de espiras de la bobina y la intensidad de corriente que circula por ella", explicacion: "La fuerza magnetomotriz (f.m.m.) es el producto entre el número de espiras (N) de una bobina y la intensidad de corriente (I) que circula por ella, siendo la causa que genera el flujo magnético." }
];

const TEMA_MAQUINAS_U3_DATA = [
  { id: 800301, tema: "U3: Interpretación de documentación técnica en máquinas eléctricas (TEST OFICIAL)", texto: "¿En qué norma se recoge la simbología eléctrica normalizada de uso más común?", opciones: ["IEC 1082-1", "ISO 9001", "UNE-EN 60204", "RD 842/2002"], correctaTexto: "IEC 1082-1", explicacion: "La simbología que se utiliza habitualmente viene recogida en la norma IEC 1082-1, que establece los símbolos gráficos y reglas para diseñar esquemas." },
  { id: 800302, tema: "U3: Interpretación de documentación técnica en máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué tipo de esquema eléctrico representa todos los elementos de forma unitaria sobre una línea, generalmente vertical, indicando con trazos oblicuos el número de conductores?", opciones: ["Esquema unifilar", "Esquema funcional", "Esquema multifilar", "Esquema de bloques"], correctaTexto: "Esquema unifilar", explicacion: "El esquema unifilar representa todos los elementos de forma unitaria sobre una línea, indicando mediante trazos oblicuos el número de elementos o conductores por tramo." },
  { id: 800303, tema: "U3: Interpretación de documentación técnica en máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué color de conductor corresponde a la fase 1 (L1) en corriente alterna según la designación normalizada?", opciones: ["Negro", "Marrón", "Gris", "Azul"], correctaTexto: "Negro", explicacion: "Según la tabla de designación de elementos, la corriente alterna de fase 1 (L1) se representa con conductor de color negro." },
  { id: 800304, tema: "U3: Interpretación de documentación técnica en máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué es un esquema multifilar en electrotecnia?", opciones: ["Un esquema que representa cada conductor de forma individual e independiente", "Un esquema que agrupa todos los conductores en una única línea", "Un esquema exclusivo de instalaciones neumáticas", "Un esquema que no incluye ningún tipo de componente eléctrico"], correctaTexto: "Un esquema que representa cada conductor de forma individual e independiente", explicacion: "A diferencia del esquema unifilar, el esquema multifilar representa cada conductor de forma individual, mostrando con detalle todas las conexiones del circuito." },
  { id: 800305, tema: "U3: Interpretación de documentación técnica en máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué es un esquema de conexiones o de bornes?", opciones: ["Un esquema que muestra la disposición física de los terminales o bornes de un equipo y sus conexiones reales", "Un esquema exclusivamente teórico sin relación con la disposición física real", "Un esquema que representa únicamente el funcionamiento lógico sin conexiones físicas", "Un tipo de plano arquitectónico"], correctaTexto: "Un esquema que muestra la disposición física de los terminales o bornes de un equipo y sus conexiones reales", explicacion: "El esquema de conexiones o de bornes representa la disposición física real de los terminales de un equipo y el cableado necesario para su conexión, facilitando el montaje práctico." },
  { id: 800306, tema: "U3: Interpretación de documentación técnica en máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué información suele incluir la placa de características de un motor eléctrico según la norma correspondiente?", opciones: ["Potencia nominal, tensión, intensidad, frecuencia, velocidad y clase de aislamiento", "Solo el nombre comercial del motor", "Únicamente el país de fabricación", "Solo el peso del motor en kg"], correctaTexto: "Potencia nominal, tensión, intensidad, frecuencia, velocidad y clase de aislamiento", explicacion: "La placa de características de un motor eléctrico debe incluir, entre otros datos normalizados, la potencia nominal, tensión, intensidad, frecuencia, velocidad de giro y clase de aislamiento térmico." },
  { id: 800307, tema: "U3: Interpretación de documentación técnica en máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué designa el código IP (Índice de Protección) en la placa de una máquina eléctrica?", opciones: ["El grado de protección de la envolvente frente a la entrada de sólidos y líquidos", "La potencia nominal de la máquina", "El fabricante y país de origen", "La clase de aislamiento térmico del bobinado"], correctaTexto: "El grado de protección de la envolvente frente a la entrada de sólidos y líquidos", explicacion: "El código IP, seguido de dos cifras, indica el grado de protección de la envolvente de la máquina frente a la entrada de cuerpos sólidos extraños (primera cifra) y de líquidos (segunda cifra)." },
  { id: 800308, tema: "U3: Interpretación de documentación técnica en máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué representa la letra que acompaña a la clase de aislamiento térmico de un motor (por ejemplo, clase F)?", opciones: ["La temperatura máxima que puede soportar el aislamiento del bobinado sin degradarse", "El tipo de material conductor del bobinado", "El grado de protección frente a polvo y agua", "El número de polos del motor"], correctaTexto: "La temperatura máxima que puede soportar el aislamiento del bobinado sin degradarse", explicacion: "La clase de aislamiento térmico (A, B, E, F, H, etc.) indica la temperatura máxima que puede soportar el material aislante del bobinado sin sufrir una degradación acelerada." },
  { id: 800309, tema: "U3: Interpretación de documentación técnica en máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué símbolo normalizado representa habitualmente un motor eléctrico en un esquema unifilar?", opciones: ["Un círculo con la letra M en su interior", "Un cuadrado con una cruz interior", "Un triángulo invertido", "Una línea discontinua sin ningún símbolo"], correctaTexto: "Un círculo con la letra M en su interior", explicacion: "El símbolo normalizado más habitual para representar un motor eléctrico en un esquema unifilar es un círculo con la letra M en su interior." },
  { id: 800310, tema: "U3: Interpretación de documentación técnica en máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué es un esquema funcional o de principio?", opciones: ["Un esquema que representa el funcionamiento lógico de una instalación sin atender a la disposición física real", "Un esquema exclusivo para representar la disposición mecánica de los componentes", "Un plano de la ubicación física del edificio", "Un documento exclusivamente administrativo sin contenido técnico"], correctaTexto: "Un esquema que representa el funcionamiento lógico de una instalación sin atender a la disposición física real", explicacion: "El esquema funcional o de principio representa el funcionamiento lógico y eléctrico de una instalación, facilitando su comprensión, sin necesidad de reflejar la disposición física real de los componentes." },
  { id: 800311, tema: "U3: Interpretación de documentación técnica en máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué color de conductor corresponde habitualmente al neutro en instalaciones de corriente alterna según la normativa española?", opciones: ["Azul claro", "Verde-amarillo", "Marrón", "Negro"], correctaTexto: "Azul claro", explicacion: "Según la normativa española, el conductor neutro se identifica habitualmente con el color azul claro, reservándose el bicolor verde-amarillo exclusivamente para el conductor de protección." },
  { id: 800312, tema: "U3: Interpretación de documentación técnica en máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué color de conductor está reservado exclusivamente para el conductor de protección (tierra)?", opciones: ["Bicolor verde-amarillo", "Azul claro", "Negro", "Marrón"], correctaTexto: "Bicolor verde-amarillo", explicacion: "El conductor de protección (tierra) está identificado de forma exclusiva y normalizada con el color bicolor verde-amarillo, no pudiéndose utilizar para ningún otro conductor activo." },
  { id: 800313, tema: "U3: Interpretación de documentación técnica en máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué es una lista de materiales (BOM) asociada a un esquema eléctrico?", opciones: ["Un documento que detalla todos los componentes y cantidades necesarios para ejecutar la instalación representada en el esquema", "Un documento exclusivamente decorativo sin ninguna utilidad práctica", "Un tipo de esquema eléctrico alternativo al unifilar", "Un documento que sustituye completamente al esquema eléctrico"], correctaTexto: "Un documento que detalla todos los componentes y cantidades necesarios para ejecutar la instalación representada en el esquema", explicacion: "La lista de materiales (Bill of Materials, BOM) detalla todos los componentes, referencias y cantidades necesarias para ejecutar físicamente la instalación representada en el esquema eléctrico." },
  { id: 800314, tema: "U3: Interpretación de documentación técnica en máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué finalidad tiene el manual de instrucciones de una máquina eléctrica?", opciones: ["Informar sobre su correcta instalación, uso, mantenimiento y medidas de seguridad", "Servir exclusivamente como documento publicitario del fabricante", "Sustituir a la placa de características de la máquina", "No tener ninguna relevancia técnica ni legal"], correctaTexto: "Informar sobre su correcta instalación, uso, mantenimiento y medidas de seguridad", explicacion: "El manual de instrucciones proporciona información esencial sobre la correcta instalación, uso, mantenimiento y medidas de seguridad que deben observarse al trabajar con la máquina eléctrica." },
  { id: 800315, tema: "U3: Interpretación de documentación técnica en máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué es el marcado CE en una máquina eléctrica?", opciones: ["Un distintivo que certifica que el producto cumple con la normativa europea de seguridad y salud aplicable", "Una marca comercial exclusiva de un único fabricante", "Un indicador del país de fabricación de la máquina", "Un código que identifica solo el año de fabricación"], correctaTexto: "Un distintivo que certifica que el producto cumple con la normativa europea de seguridad y salud aplicable", explicacion: "El marcado CE es un distintivo obligatorio que certifica que el producto cumple con los requisitos esenciales de seguridad y salud establecidos por la normativa europea aplicable." },
  { id: 800316, tema: "U3: Interpretación de documentación técnica en máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué es una hoja de despiece en la documentación técnica de una máquina eléctrica?", opciones: ["Un documento gráfico que muestra todas las piezas de la máquina de forma individualizada, facilitando su identificación y sustitución", "Un documento exclusivamente comercial sin utilidad técnica", "Un esquema eléctrico simplificado sin ninguna representación mecánica", "Un manual de seguridad laboral genérico"], correctaTexto: "Un documento gráfico que muestra todas las piezas de la máquina de forma individualizada, facilitando su identificación y sustitución", explicacion: "La hoja de despiece es un documento gráfico que muestra de forma individualizada todas las piezas que componen la máquina, facilitando su identificación a la hora de solicitar recambios o realizar reparaciones." },
  { id: 800317, tema: "U3: Interpretación de documentación técnica en máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué es la designación IEC de un motor trifásico según su forma constructiva (por ejemplo, IM B3)?", opciones: ["Un código normalizado que indica el tipo de fijación y disposición del motor (patas, brida, eje horizontal o vertical, etc.)", "Un código que indica exclusivamente el color de la carcasa del motor", "Un código que representa el número de fases del motor", "Un código exclusivo para motores monofásicos"], correctaTexto: "Un código normalizado que indica el tipo de fijación y disposición del motor (patas, brida, eje horizontal o vertical, etc.)", explicacion: "La designación IEC de forma constructiva (IM, International Mounting) indica de forma normalizada el tipo de fijación y disposición del motor, como montaje sobre patas, con brida, en posición horizontal o vertical." },
  { id: 800318, tema: "U3: Interpretación de documentación técnica en máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué es un diagrama de tiempos en la documentación técnica de un automatismo eléctrico?", opciones: ["Una representación gráfica de la secuencia temporal en que se activan y desactivan los distintos elementos de un circuito", "Un tipo de esquema unifilar simplificado", "Un documento exclusivo para instalaciones de telecomunicación", "Un listado de precios de los componentes del automatismo"], correctaTexto: "Una representación gráfica de la secuencia temporal en que se activan y desactivan los distintos elementos de un circuito", explicacion: "El diagrama de tiempos representa gráficamente la secuencia temporal de activación y desactivación de los distintos elementos de un automatismo, facilitando la comprensión de su funcionamiento." },
  { id: 800319, tema: "U3: Interpretación de documentación técnica en máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué simbología se emplea para representar un contacto normalmente abierto (NA) en un esquema eléctrico normalizado?", opciones: ["Dos líneas paralelas separadas que se cierran al activarse el contacto", "Dos líneas paralelas ya unidas de forma permanente", "Un círculo relleno de color negro", "Una flecha apuntando hacia abajo"], correctaTexto: "Dos líneas paralelas separadas que se cierran al activarse el contacto", explicacion: "El contacto normalmente abierto (NA) se representa mediante dos líneas paralelas separadas que permanecen abiertas en reposo y se cierran al activarse el elemento correspondiente (relé, contactor, etc.)." },
  { id: 800320, tema: "U3: Interpretación de documentación técnica en máquinas eléctricas (TEST OFICIAL)", texto: "¿Qué representa el símbolo normalizado de un contacto normalmente cerrado (NC) en un esquema eléctrico?", opciones: ["Un contacto que permanece cerrado en reposo y se abre al activarse el elemento correspondiente", "Un contacto que nunca puede cambiar de estado", "Un contacto exclusivo de circuitos neumáticos", "Un símbolo idéntico al del contacto normalmente abierto sin ninguna diferencia"], correctaTexto: "Un contacto que permanece cerrado en reposo y se abre al activarse el elemento correspondiente", explicacion: "El contacto normalmente cerrado (NC) permanece cerrado en condiciones de reposo, abriéndose al activarse el elemento asociado (relé, contactor, pulsador, etc.), representándose con una simbología específica diferente al contacto NA." }
];

const TEMA_MAQUINAS_U4_DATA = [
  { id: 800401, tema: "U4: Construcción de transformadores eléctricos de pequeña potencia (TEST OFICIAL)", texto: "¿Cómo se denomina el proceso de transformación de un transformador de tensión mediante dos arrollamientos primario y secundario?", opciones: ["Transformación de energía eléctrica por inducción electromagnética", "Rectificación de corriente", "Conmutación mecánica", "Amplificación de señal"], correctaTexto: "Transformación de energía eléctrica por inducción electromagnética", explicacion: "Un transformador es una máquina eléctrica estática que funciona con corriente alterna, constituida por dos arrollamientos que hacen posible la transformación de energía eléctrica por inducción." },
  { id: 800402, tema: "U4: Construcción de transformadores eléctricos de pequeña potencia (TEST OFICIAL)", texto: "¿Qué corrientes parásitas se busca limitar aislando entre sí las chapas del núcleo del transformador?", opciones: ["Las corrientes de Foucault", "Las corrientes de cortocircuito", "Las corrientes de fuga", "Las corrientes armónicas"], correctaTexto: "Las corrientes de Foucault", explicacion: "El aislamiento entre chapas del núcleo se justifica por el interés de limitar al máximo las pérdidas ocasionadas por las corrientes de Foucault." },
  { id: 800403, tema: "U4: Construcción de transformadores eléctricos de pequeña potencia (TEST OFICIAL)", texto: "¿Qué característica distingue a un autotransformador de un transformador convencional?", opciones: ["Los circuitos primario y secundario están físicamente unidos formando un devanado continuo", "No requiere corriente alterna para funcionar", "Solo puede ser elevador, nunca reductor", "No tiene núcleo magnético"], correctaTexto: "Los circuitos primario y secundario están físicamente unidos formando un devanado continuo", explicacion: "En los autotransformadores los circuitos primario y secundario están físicamente unidos, formados por un devanado continuo, a diferencia de los transformadores convencionales." },
  { id: 800404, tema: "U4: Construcción de transformadores eléctricos de pequeña potencia (TEST OFICIAL)", texto: "¿Qué es la relación de transformación de un transformador?", opciones: ["El cociente entre el número de espiras del primario y del secundario", "El cociente entre la potencia de entrada y de salida", "La diferencia de temperatura entre primario y secundario", "El cociente entre las secciones de los núcleos magnéticos"], correctaTexto: "El cociente entre el número de espiras del primario y del secundario", explicacion: "La relación de transformación es el cociente entre el número de espiras del devanado primario y del devanado secundario, determinando la relación entre las tensiones de ambos." },
  { id: 800405, tema: "U4: Construcción de transformadores eléctricos de pequeña potencia (TEST OFICIAL)", texto: "¿Qué material se emplea habitualmente para fabricar el núcleo magnético de un transformador de pequeña potencia?", opciones: ["Chapa de acero al silicio laminada", "Cobre puro macizo", "Aluminio macizo", "Plástico reforzado con fibra de vidrio"], correctaTexto: "Chapa de acero al silicio laminada", explicacion: "El núcleo magnético de los transformadores se fabrica habitualmente con chapa de acero al silicio laminada, que ofrece buenas propiedades magnéticas y reduce las pérdidas por corrientes parásitas." },
  { id: 800406, tema: "U4: Construcción de transformadores eléctricos de pequeña potencia (TEST OFICIAL)", texto: "¿Qué tipo de núcleo se caracteriza por tener forma de E e I, siendo muy habitual en transformadores de pequeña potencia?", opciones: ["Núcleo tipo acorazado", "Núcleo toroidal", "Núcleo tipo columnas sin culatas", "Núcleo de aire sin material ferromagnético"], correctaTexto: "Núcleo tipo acorazado", explicacion: "El núcleo tipo acorazado, formado por chapas en forma de E e I, es muy habitual en transformadores de pequeña potencia por su sencillez constructiva y buen rendimiento." },
  { id: 800407, tema: "U4: Construcción de transformadores eléctricos de pequeña potencia (TEST OFICIAL)", texto: "¿Qué ventaja presenta el núcleo toroidal frente al núcleo acorazado en transformadores de pequeña potencia?", opciones: ["Menor dispersión de flujo magnético y menor nivel de ruido", "Mayor peso y volumen para la misma potencia", "Mayor dificultad de bobinado sin ninguna ventaja eléctrica", "Menor rendimiento eléctrico en todos los casos"], correctaTexto: "Menor dispersión de flujo magnético y menor nivel de ruido", explicacion: "El núcleo toroidal presenta menor dispersión de flujo magnético y genera menos ruido en funcionamiento, aunque su proceso de bobinado resulta más complejo que el del núcleo acorazado." },
  { id: 800408, tema: "U4: Construcción de transformadores eléctricos de pequeña potencia (TEST OFICIAL)", texto: "¿Qué es el devanado primario de un transformador?", opciones: ["El bobinado que recibe la energía eléctrica de la red de alimentación", "El bobinado que entrega la energía transformada a la carga", "Un bobinado exclusivo de los autotransformadores", "Un elemento que no forma parte del circuito eléctrico del transformador"], correctaTexto: "El bobinado que recibe la energía eléctrica de la red de alimentación", explicacion: "El devanado primario es el bobinado que recibe la energía eléctrica procedente de la red de alimentación, transfiriéndola por inducción electromagnética al devanado secundario." },
  { id: 800409, tema: "U4: Construcción de transformadores eléctricos de pequeña potencia (TEST OFICIAL)", texto: "¿Qué es el devanado secundario de un transformador?", opciones: ["El bobinado que entrega la energía eléctrica transformada a la carga conectada", "El bobinado que recibe directamente la energía de la red eléctrica", "Un elemento decorativo sin función eléctrica", "El núcleo magnético del transformador"], correctaTexto: "El bobinado que entrega la energía eléctrica transformada a la carga conectada", explicacion: "El devanado secundario es el bobinado que recibe la energía transferida por inducción desde el primario y la entrega, con la tensión transformada, a la carga conectada." },
  { id: 800410, tema: "U4: Construcción de transformadores eléctricos de pequeña potencia (TEST OFICIAL)", texto: "¿Qué es un transformador elevador de tensión?", opciones: ["Un transformador cuya tensión de salida en el secundario es mayor que la tensión de entrada en el primario", "Un transformador cuya tensión de salida es siempre menor que la de entrada", "Un transformador que no modifica en absoluto la tensión de entrada", "Un transformador exclusivo para corriente continua"], correctaTexto: "Un transformador cuya tensión de salida en el secundario es mayor que la tensión de entrada en el primario", explicacion: "Un transformador elevador es aquel en el que el devanado secundario tiene mayor número de espiras que el primario, resultando en una tensión de salida superior a la de entrada." },
  { id: 800411, tema: "U4: Construcción de transformadores eléctricos de pequeña potencia (TEST OFICIAL)", texto: "¿Qué es un transformador reductor de tensión?", opciones: ["Un transformador cuya tensión de salida en el secundario es menor que la tensión de entrada en el primario", "Un transformador cuya tensión de salida es siempre mayor que la de entrada", "Un transformador que solo funciona en corriente continua", "Un transformador sin ningún tipo de núcleo magnético"], correctaTexto: "Un transformador cuya tensión de salida en el secundario es menor que la tensión de entrada en el primario", explicacion: "Un transformador reductor es aquel en el que el devanado secundario tiene menor número de espiras que el primario, entregando una tensión de salida inferior a la de entrada." },
  { id: 800412, tema: "U4: Construcción de transformadores eléctricos de pequeña potencia (TEST OFICIAL)", texto: "¿Qué es el aislamiento entre espiras en el bobinado de un transformador y por qué es necesario?", opciones: ["Un recubrimiento aislante que evita cortocircuitos entre espiras adyacentes del mismo devanado", "Un aislamiento que solo se aplica entre el primario y el secundario, nunca dentro de un mismo devanado", "Un elemento decorativo sin función eléctrica real", "Un aislamiento que solo existe en los transformadores de gran potencia"], correctaTexto: "Un recubrimiento aislante que evita cortocircuitos entre espiras adyacentes del mismo devanado", explicacion: "El aislamiento entre espiras, habitualmente mediante el esmalte del propio hilo de cobre, evita que se produzcan cortocircuitos entre espiras adyacentes de un mismo devanado, protegiendo la integridad de la máquina." },
  { id: 800413, tema: "U4: Construcción de transformadores eléctricos de pequeña potencia (TEST OFICIAL)", texto: "¿Qué finalidad tiene la carcasa o envolvente exterior de un transformador de pequeña potencia?", opciones: ["Proteger mecánicamente el núcleo y los bobinados, y evitar el contacto accidental con partes en tensión", "Aumentar exclusivamente el peso del transformador sin ninguna función de protección", "Servir como conductor eléctrico adicional del circuito secundario", "Sustituir la función del núcleo magnético"], correctaTexto: "Proteger mecánicamente el núcleo y los bobinados, y evitar el contacto accidental con partes en tensión", explicacion: "La carcasa o envolvente protege mecánicamente el núcleo y los bobinados del transformador frente a golpes y agentes externos, además de evitar el contacto accidental de personas con partes en tensión." },
  { id: 800414, tema: "U4: Construcción de transformadores eléctricos de pequeña potencia (TEST OFICIAL)", texto: "¿Qué elemento del transformador permite la conexión eléctrica con los circuitos exteriores?", opciones: ["Los bornes o terminales de conexión", "El núcleo magnético exclusivamente", "La carcasa metálica sin ninguna conexión eléctrica", "El aislamiento entre espiras"], correctaTexto: "Los bornes o terminales de conexión", explicacion: "Los bornes o terminales de conexión son los puntos accesibles del transformador que permiten conectarlo eléctricamente a los circuitos exteriores, tanto en el primario como en el secundario." },
  { id: 800415, tema: "U4: Construcción de transformadores eléctricos de pequeña potencia (TEST OFICIAL)", texto: "¿Qué tipo de transformador de pequeña potencia se utiliza habitualmente para alimentar circuitos de control y timbres a muy baja tensión de seguridad?", opciones: ["El transformador de seguridad o de campanilla", "El transformador de potencia industrial de gran tamaño", "El transformador trifásico de distribución", "El autotransformador variable de laboratorio"], correctaTexto: "El transformador de seguridad o de campanilla", explicacion: "El transformador de seguridad, también llamado transformador de campanilla, reduce la tensión de red a valores de muy baja tensión de seguridad para alimentar circuitos de control, timbres o juguetes." },
  { id: 800416, tema: "U4: Construcción de transformadores eléctricos de pequeña potencia (TEST OFICIAL)", texto: "¿Qué es el rendimiento de un transformador?", opciones: ["La relación entre la potencia entregada en el secundario y la potencia absorbida en el primario", "La relación entre el número de espiras del primario y del secundario", "La diferencia de temperatura entre el primario y el secundario", "El peso total del transformador dividido entre su potencia nominal"], correctaTexto: "La relación entre la potencia entregada en el secundario y la potencia absorbida en el primario", explicacion: "El rendimiento de un transformador es la relación entre la potencia útil entregada en el secundario y la potencia total absorbida en el primario, siendo siempre inferior al 100% debido a las pérdidas." },
  { id: 800417, tema: "U4: Construcción de transformadores eléctricos de pequeña potencia (TEST OFICIAL)", texto: "¿Qué es un transformador de aislamiento y para qué se utiliza?", opciones: ["Un transformador con relación de transformación 1:1 que separa eléctricamente dos circuitos por motivos de seguridad", "Un transformador que siempre eleva la tensión al doble de su valor de entrada", "Un transformador exclusivo para corriente continua sin ningún uso en corriente alterna", "Un transformador que no requiere núcleo magnético"], correctaTexto: "Un transformador con relación de transformación 1:1 que separa eléctricamente dos circuitos por motivos de seguridad", explicacion: "El transformador de aislamiento, con relación de transformación 1:1, separa galvánicamente dos circuitos eléctricos, aportando seguridad frente a contactos eléctricos indirectos, sin modificar el valor de la tensión." },
  { id: 800418, tema: "U4: Construcción de transformadores eléctricos de pequeña potencia (TEST OFICIAL)", texto: "¿Qué proceso de fabricación permite obtener los devanados de un transformador de pequeña potencia?", opciones: ["El bobinado del hilo de cobre esmaltado sobre el carrete o soporte del núcleo", "La fundición directa del cobre sobre el núcleo magnético", "El mecanizado por arranque de viruta del núcleo", "La soldadura directa de láminas de cobre sin bobinado alguno"], correctaTexto: "El bobinado del hilo de cobre esmaltado sobre el carrete o soporte del núcleo", explicacion: "Los devanados de un transformador de pequeña potencia se obtienen bobinando el hilo de cobre esmaltado sobre el carrete o soporte que envuelve el núcleo magnético, siguiendo el número de espiras calculado." },
  { id: 800419, tema: "U4: Construcción de transformadores eléctricos de pequeña potencia (TEST OFICIAL)", texto: "¿Qué comprobación se debe realizar tras finalizar la construcción de un transformador, antes de su puesta en servicio?", opciones: ["Verificar la resistencia de aislamiento entre devanados y respecto a la carcasa, y comprobar la relación de transformación", "Ponerlo en marcha directamente sin ninguna comprobación previa", "Solo comprobar el aspecto estético del bobinado", "Medir exclusivamente el peso del transformador terminado"], correctaTexto: "Verificar la resistencia de aislamiento entre devanados y respecto a la carcasa, y comprobar la relación de transformación", explicacion: "Antes de poner en servicio un transformador recién construido se debe verificar la resistencia de aislamiento entre devanados y respecto a la carcasa, así como comprobar que la relación de transformación es la correcta." },
  { id: 800420, tema: "U4: Construcción de transformadores eléctricos de pequeña potencia (TEST OFICIAL)", texto: "¿Qué es un transformador con tomas o derivaciones (taps) en el devanado?", opciones: ["Un transformador que permite seleccionar distintas relaciones de transformación conectando el circuito a diferentes puntos del devanado", "Un transformador con un único valor de tensión de salida fijo e inmodificable", "Un transformador exclusivo para corriente continua", "Un transformador sin ningún tipo de devanado secundario"], correctaTexto: "Un transformador que permite seleccionar distintas relaciones de transformación conectando el circuito a diferentes puntos del devanado", explicacion: "Un transformador con tomas o derivaciones incorpora varios puntos de conexión intermedios en el devanado, permitiendo seleccionar distintas relaciones de transformación y adaptar la tensión de salida a diferentes necesidades." }
];

const TEMA_MAQUINAS_U5_DATA = [
  { id: 800501, tema: "U5: Ensayos de transformadores eléctricos (TEST OFICIAL)", texto: "¿Qué determina el ensayo en vacío de un transformador?", opciones: ["Las pérdidas de potencia en el hierro del circuito magnético", "Las pérdidas en el cobre exclusivamente", "La resistencia de aislamiento del aceite", "La velocidad de rotación del rotor"], correctaTexto: "Las pérdidas de potencia en el hierro del circuito magnético", explicacion: "El ensayo en vacío determina las pérdidas de potencia en el hierro del circuito magnético del transformador, abriendo el secundario y alimentando el primario a tensión nominal." },
  { id: 800502, tema: "U5: Ensayos de transformadores eléctricos (TEST OFICIAL)", texto: "¿Qué pérdidas se obtienen principalmente en el ensayo de cortocircuito de un transformador?", opciones: ["Las pérdidas en el cobre por efecto Joule", "Las pérdidas en el hierro", "Las pérdidas por rozamiento mecánico", "Las pérdidas dieléctricas del aceite"], correctaTexto: "Las pérdidas en el cobre por efecto Joule", explicacion: "En el ensayo de cortocircuito las pérdidas en el hierro son despreciables y las pérdidas se generan esencialmente por efecto Joule en los bobinados, conocidas como pérdidas en el cobre." },
  { id: 800503, tema: "U5: Ensayos de transformadores eléctricos (TEST OFICIAL)", texto: "¿Con qué dispositivo se mide la resistencia de aislamiento entre los bobinados de un transformador?", opciones: ["El megóhmetro", "El vatímetro", "El fasímetro", "El tacómetro"], correctaTexto: "El megóhmetro", explicacion: "Para medir la resistencia de aislamiento entre bobinados y entre estos y la carcasa se utiliza un dispositivo denominado megóhmetro (MΩ)." },
  { id: 800504, tema: "U5: Ensayos de transformadores eléctricos (TEST OFICIAL)", texto: "¿Qué condiciones se establecen al realizar el ensayo en vacío de un transformador?", opciones: ["El secundario permanece abierto (sin carga) y se alimenta el primario a tensión nominal", "El secundario se cortocircuita y se alimenta el primario a tensión reducida", "Ambos devanados permanecen desconectados de cualquier fuente", "El primario se cortocircuita y se mide directamente en el secundario"], correctaTexto: "El secundario permanece abierto (sin carga) y se alimenta el primario a tensión nominal", explicacion: "En el ensayo en vacío, el devanado secundario permanece abierto (sin carga conectada) mientras se alimenta el primario a su tensión nominal, midiendo la potencia absorbida (pérdidas en el hierro)." },
  { id: 800505, tema: "U5: Ensayos de transformadores eléctricos (TEST OFICIAL)", texto: "¿Qué condiciones se establecen al realizar el ensayo de cortocircuito de un transformador?", opciones: ["El secundario se cortocircuita y se alimenta el primario a tensión reducida hasta obtener la intensidad nominal", "El secundario permanece abierto y se alimenta el primario a tensión nominal", "Ambos devanados se desconectan completamente de la red", "Se aplica directamente la tensión nominal completa sobre el secundario cortocircuitado"], correctaTexto: "El secundario se cortocircuita y se alimenta el primario a tensión reducida hasta obtener la intensidad nominal", explicacion: "En el ensayo de cortocircuito se cortocircuita el devanado secundario y se alimenta el primario con una tensión reducida, incrementándola gradualmente hasta que circule la intensidad nominal por los devanados." },
  { id: 800506, tema: "U5: Ensayos de transformadores eléctricos (TEST OFICIAL)", texto: "¿Qué instrumento se emplea para medir la potencia absorbida durante los ensayos de un transformador?", opciones: ["El vatímetro", "El megóhmetro", "El tacómetro", "El calibre"], correctaTexto: "El vatímetro", explicacion: "El vatímetro es el instrumento utilizado para medir la potencia eléctrica absorbida por el transformador durante los ensayos en vacío y de cortocircuito." },
  { id: 800507, tema: "U5: Ensayos de transformadores eléctricos (TEST OFICIAL)", texto: "¿Qué se calcula a partir de los resultados de los ensayos en vacío y de cortocircuito de un transformador?", opciones: ["El rendimiento del transformador a distintos regímenes de carga", "Únicamente el peso total del transformador", "El color del aislamiento del bobinado", "La velocidad de giro del núcleo magnético"], correctaTexto: "El rendimiento del transformador a distintos regímenes de carga", explicacion: "A partir de las pérdidas en el hierro (ensayo en vacío) y en el cobre (ensayo de cortocircuito), se puede calcular el rendimiento del transformador para distintos regímenes de carga." },
  { id: 800508, tema: "U5: Ensayos de transformadores eléctricos (TEST OFICIAL)", texto: "¿Qué es la tensión de cortocircuito porcentual (Ucc%) de un transformador?", opciones: ["El porcentaje de la tensión nominal necesario para hacer circular la intensidad nominal con el secundario en cortocircuito", "La tensión nominal completa aplicada al primario en condiciones normales", "La tensión máxima que soporta el aislamiento del transformador", "La diferencia de tensión entre el primario y el secundario en vacío"], correctaTexto: "El porcentaje de la tensión nominal necesario para hacer circular la intensidad nominal con el secundario en cortocircuito", explicacion: "La tensión de cortocircuito porcentual (Ucc%) indica qué porcentaje de la tensión nominal del primario es necesario aplicar para que circule la intensidad nominal con el secundario cortocircuitado, siendo un dato característico del transformador." },
  { id: 800509, tema: "U5: Ensayos de transformadores eléctricos (TEST OFICIAL)", texto: "¿Qué ensayo permite determinar la relación de transformación real de un transformador ya construido?", opciones: ["El ensayo de relación de transformación, comparando tensiones de primario y secundario en vacío", "El ensayo de cortocircuito exclusivamente", "El ensayo de resistencia de aislamiento exclusivamente", "El ensayo de rigidez dieléctrica del aceite"], correctaTexto: "El ensayo de relación de transformación, comparando tensiones de primario y secundario en vacío", explicacion: "El ensayo de relación de transformación consiste en medir las tensiones en primario y secundario con el transformador en vacío, comparando el resultado con la relación de espiras teórica de diseño." },
  { id: 800510, tema: "U5: Ensayos de transformadores eléctricos (TEST OFICIAL)", texto: "¿Qué ensayo verifica que el aislamiento de un transformador soporta una sobretensión determinada sin producirse una descarga disruptiva?", opciones: ["El ensayo de rigidez dieléctrica", "El ensayo en vacío", "El ensayo de cortocircuito", "El ensayo de relación de transformación"], correctaTexto: "El ensayo de rigidez dieléctrica", explicacion: "El ensayo de rigidez dieléctrica somete al aislamiento del transformador a una tensión superior a la nominal durante un tiempo determinado, verificando que no se produce una descarga disruptiva a través del aislante." },
  { id: 800511, tema: "U5: Ensayos de transformadores eléctricos (TEST OFICIAL)", texto: "¿Qué valor mínimo de resistencia de aislamiento se suele considerar aceptable en un transformador de pequeña potencia?", opciones: ["Un valor de varios megaohmios (MΩ), según la normativa aplicable", "Un valor inferior a 1 ohmio", "No existe ningún valor mínimo de referencia", "Un valor negativo, indicando cortocircuito franco"], correctaTexto: "Un valor de varios megaohmios (MΩ), según la normativa aplicable", explicacion: "La resistencia de aislamiento aceptable en un transformador debe alcanzar varios megaohmios (MΩ), según los criterios establecidos en la normativa técnica aplicable, para garantizar un aislamiento seguro." },
  { id: 800512, tema: "U5: Ensayos de transformadores eléctricos (TEST OFICIAL)", texto: "¿Qué ensayo permite verificar el correcto funcionamiento térmico de un transformador bajo carga continuada?", opciones: ["El ensayo de calentamiento", "El ensayo de relación de transformación", "El ensayo de resistencia de aislamiento en frío", "El ensayo de vacío a tensión reducida"], correctaTexto: "El ensayo de calentamiento", explicacion: "El ensayo de calentamiento verifica que la temperatura alcanzada por el transformador bajo carga continuada no supera los límites admisibles según su clase de aislamiento térmico." },
  { id: 800513, tema: "U5: Ensayos de transformadores eléctricos (TEST OFICIAL)", texto: "¿Qué relación existe entre las pérdidas en el hierro y la carga del transformador?", opciones: ["Las pérdidas en el hierro son prácticamente constantes, independientes del régimen de carga", "Las pérdidas en el hierro aumentan proporcionalmente con la carga", "Las pérdidas en el hierro solo aparecen cuando el transformador está en cortocircuito", "Las pérdidas en el hierro son nulas en cualquier condición de funcionamiento"], correctaTexto: "Las pérdidas en el hierro son prácticamente constantes, independientes del régimen de carga", explicacion: "Las pérdidas en el hierro (por histéresis y corrientes de Foucault) dependen principalmente de la tensión y frecuencia aplicadas, permaneciendo prácticamente constantes independientemente del régimen de carga del transformador." },
  { id: 800514, tema: "U5: Ensayos de transformadores eléctricos (TEST OFICIAL)", texto: "¿Qué relación existe entre las pérdidas en el cobre y la carga del transformador?", opciones: ["Las pérdidas en el cobre son proporcionales al cuadrado de la intensidad de carga (I²·R)", "Las pérdidas en el cobre son siempre constantes, independientes de la carga", "Las pérdidas en el cobre solo existen en vacío", "Las pérdidas en el cobre disminuyen al aumentar la carga"], correctaTexto: "Las pérdidas en el cobre son proporcionales al cuadrado de la intensidad de carga (I²·R)", explicacion: "Las pérdidas en el cobre, producidas por efecto Joule en los devanados, son proporcionales al cuadrado de la intensidad que circula por ellos (I²·R), aumentando notablemente al incrementarse la carga." },
  { id: 800515, tema: "U5: Ensayos de transformadores eléctricos (TEST OFICIAL)", texto: "¿Qué precaución de seguridad es fundamental antes de realizar los ensayos eléctricos de un transformador?", opciones: ["Verificar la ausencia de tensión residual y utilizar equipos de medida adecuados a la tensión de ensayo", "Realizar los ensayos con el transformador conectado directamente a la red sin ninguna comprobación previa", "Ignorar cualquier medida de seguridad si el ensayo es breve", "Utilizar cualquier instrumento de medida sin comprobar su rango de tensión"], correctaTexto: "Verificar la ausencia de tensión residual y utilizar equipos de medida adecuados a la tensión de ensayo", explicacion: "Antes de realizar cualquier ensayo eléctrico sobre un transformador debe verificarse la ausencia de tensión residual y emplear equipos de medida adecuados al rango de tensión previsto, respetando las normas de seguridad." },
  { id: 800516, tema: "U5: Ensayos de transformadores eléctricos (TEST OFICIAL)", texto: "¿Qué es el 'punto de máximo rendimiento' de un transformador?", opciones: ["El nivel de carga en el que las pérdidas en el cobre igualan a las pérdidas en el hierro", "El nivel de carga en el que el transformador entrega su potencia nominal máxima sin ninguna pérdida", "El punto en que el transformador trabaja completamente en vacío", "El punto en que la tensión secundaria es nula"], correctaTexto: "El nivel de carga en el que las pérdidas en el cobre igualan a las pérdidas en el hierro", explicacion: "El punto de máximo rendimiento de un transformador se produce en el nivel de carga en el que las pérdidas variables en el cobre igualan a las pérdidas constantes en el hierro." },
  { id: 800517, tema: "U5: Ensayos de transformadores eléctricos (TEST OFICIAL)", texto: "¿Qué se entiende por 'caída de tensión' en un transformador bajo carga?", opciones: ["La diferencia entre la tensión secundaria en vacío y la tensión secundaria bajo carga", "La diferencia de tensión entre las dos fases del devanado primario", "La tensión perdida exclusivamente en el núcleo magnético", "La tensión aplicada durante el ensayo de rigidez dieléctrica"], correctaTexto: "La diferencia entre la tensión secundaria en vacío y la tensión secundaria bajo carga", explicacion: "La caída de tensión de un transformador es la diferencia entre la tensión que entrega el secundario en vacío y la tensión que entrega bajo carga, debida a la impedancia interna del transformador." },
  { id: 800518, tema: "U5: Ensayos de transformadores eléctricos (TEST OFICIAL)", texto: "¿Qué documento recoge los resultados y condiciones de los ensayos realizados a un transformador?", opciones: ["El certificado o protocolo de ensayos", "La placa de características exclusivamente", "El manual de instrucciones genérico del fabricante", "El esquema unifilar de la instalación"], correctaTexto: "El certificado o protocolo de ensayos", explicacion: "El certificado o protocolo de ensayos recoge de forma documentada los resultados obtenidos y las condiciones en que se realizaron los distintos ensayos eléctricos al transformador." },
  { id: 800519, tema: "U5: Ensayos de transformadores eléctricos (TEST OFICIAL)", texto: "¿Qué relación existe entre el ensayo de cortocircuito y la determinación de la impedancia interna del transformador?", opciones: ["El ensayo de cortocircuito permite calcular la impedancia interna equivalente del transformador", "El ensayo de cortocircuito no aporta ninguna información sobre la impedancia interna", "La impedancia interna solo puede determinarse mediante el ensayo en vacío", "La impedancia interna es un dato que nunca puede calcularse mediante ensayos"], correctaTexto: "El ensayo de cortocircuito permite calcular la impedancia interna equivalente del transformador", explicacion: "A partir de la tensión y potencia medidas en el ensayo de cortocircuito, se puede calcular la impedancia interna equivalente del transformador, referida al lado en que se realiza la medida." },
  { id: 800520, tema: "U5: Ensayos de transformadores eléctricos (TEST OFICIAL)", texto: "¿Qué finalidad tiene realizar ensayos periódicos de mantenimiento sobre un transformador en servicio?", opciones: ["Detectar de forma preventiva un posible deterioro del aislamiento o un aumento anómalo de pérdidas", "Aumentar deliberadamente el consumo eléctrico del transformador", "Sustituir la necesidad de realizar cualquier mantenimiento visual", "Cumplir un trámite sin ninguna utilidad técnica real"], correctaTexto: "Detectar de forma preventiva un posible deterioro del aislamiento o un aumento anómalo de pérdidas", explicacion: "Los ensayos periódicos de mantenimiento permiten detectar de forma preventiva un posible deterioro del aislamiento o un aumento anómalo de las pérdidas, anticipándose a averías graves del transformador." }
];

const TEMA_MAQUINAS_U6_DATA = [
  { id: 800601, tema: "U6: Máquinas de corriente continua y sus bobinados (TEST OFICIAL)", texto: "¿En qué parte de la máquina de corriente continua se monta el circuito inducido?", opciones: ["Sobre el rotor", "Sobre el estator", "Sobre la carcasa", "Sobre las piezas polares"], correctaTexto: "Sobre el rotor", explicacion: "El circuito eléctrico se subdivide en excitación y conmutación (en el estator), mientras que el inducido está montado sobre el rotor." },
  { id: 800602, tema: "U6: Máquinas de corriente continua y sus bobinados (TEST OFICIAL)", texto: "¿Qué tipo de excitación tiene las bobinas conectadas de forma que el inductor y el inducido están en serie, con hilo de gran sección?", opciones: ["Excitación en serie", "Excitación shunt", "Excitación independiente", "Excitación compound"], correctaTexto: "Excitación en serie", explicacion: "En la excitación en serie el inductor y el inducido están conectados en serie, con bobinados de pocas espiras e hilo de gran sección por el que circula toda la corriente." },
  { id: 800603, tema: "U6: Máquinas de corriente continua y sus bobinados (TEST OFICIAL)", texto: "¿Qué formado por placas de cobre aisladas entre sí simula la corriente continua a partir del bobinado inducido?", opciones: ["El colector de delgas", "El bobinado inductor", "La placa de bornes", "El entrehierro"], correctaTexto: "El colector de delgas", explicacion: "El devanado inducido se conecta a un colector de delgas, formado por placas de cobre (delgas) aisladas entre sí por láminas de mica." },
  { id: 800604, tema: "U6: Máquinas de corriente continua y sus bobinados (TEST OFICIAL)", texto: "¿Qué elemento de la máquina de corriente continua permite el contacto eléctrico deslizante entre el colector de delgas (rotativo) y el circuito exterior (fijo)?", opciones: ["Las escobillas", "Las piezas polares", "El entrehierro", "El bobinado de excitación"], correctaTexto: "Las escobillas", explicacion: "Las escobillas, habitualmente de grafito o carbón, deslizan sobre el colector de delgas permitiendo el contacto eléctrico entre el circuito rotativo (inducido) y el circuito exterior fijo." },
  { id: 800605, tema: "U6: Máquinas de corriente continua y sus bobinados (TEST OFICIAL)", texto: "¿Qué es el entrehierro en una máquina de corriente continua?", opciones: ["El espacio de aire existente entre el rotor y el estator", "El aislamiento entre las escobillas y el colector", "El material aislante entre delgas del colector", "El bobinado situado en las piezas polares"], correctaTexto: "El espacio de aire existente entre el rotor y el estator", explicacion: "El entrehierro es el pequeño espacio de aire existente entre el rotor y el estator, fundamental para el correcto establecimiento del flujo magnético en la máquina." },
  { id: 800606, tema: "U6: Máquinas de corriente continua y sus bobinados (TEST OFICIAL)", texto: "¿Qué tipo de excitación conecta el bobinado inductor en paralelo con el circuito del inducido, con hilo de pequeña sección y muchas espiras?", opciones: ["Excitación shunt o derivación", "Excitación en serie", "Excitación independiente", "Excitación por imanes permanentes"], correctaTexto: "Excitación shunt o derivación", explicacion: "En la excitación shunt (o derivación) el bobinado inductor se conecta en paralelo con el inducido, empleando hilo de pequeña sección y un elevado número de espiras." },
  { id: 800607, tema: "U6: Máquinas de corriente continua y sus bobinados (TEST OFICIAL)", texto: "¿Qué tipo de excitación combina un bobinado inductor en serie y otro en paralelo con el inducido?", opciones: ["Excitación compound o mixta", "Excitación shunt pura", "Excitación en serie pura", "Excitación independiente pura"], correctaTexto: "Excitación compound o mixta", explicacion: "La excitación compound o mixta combina un bobinado inductor en serie y otro en paralelo (shunt) con el inducido, aunando las características de ambos tipos de excitación." },
  { id: 800608, tema: "U6: Máquinas de corriente continua y sus bobinados (TEST OFICIAL)", texto: "¿Qué tipo de excitación alimenta el bobinado inductor desde una fuente de alimentación externa, independiente del circuito del inducido?", opciones: ["Excitación independiente", "Excitación en serie", "Excitación shunt", "Excitación compound"], correctaTexto: "Excitación independiente", explicacion: "En la excitación independiente, el bobinado inductor se alimenta desde una fuente externa de corriente continua, totalmente independiente del circuito del inducido." },
  { id: 800609, tema: "U6: Máquinas de corriente continua y sus bobinados (TEST OFICIAL)", texto: "¿Qué elemento de la máquina de corriente continua alberga el bobinado de excitación y crea el campo magnético principal?", opciones: ["Las piezas polares (polos inductores)", "El colector de delgas", "Las escobillas", "El eje del rotor"], correctaTexto: "Las piezas polares (polos inductores)", explicacion: "Las piezas polares o polos inductores, situadas en el estator, albergan el bobinado de excitación y son las encargadas de crear el campo magnético principal de la máquina." },
  { id: 800610, tema: "U6: Máquinas de corriente continua y sus bobinados (TEST OFICIAL)", texto: "¿Qué material se emplea habitualmente en la fabricación de las escobillas de una máquina de corriente continua?", opciones: ["Grafito o carbón", "Cobre puro macizo", "Aluminio anodizado", "Plástico reforzado"], correctaTexto: "Grafito o carbón", explicacion: "Las escobillas se fabrican habitualmente de grafito o carbón, materiales que ofrecen buena conductividad eléctrica y un desgaste controlado al deslizar sobre el colector." },
  { id: 800611, tema: "U6: Máquinas de corriente continua y sus bobinados (TEST OFICIAL)", texto: "¿Qué son los polos de conmutación (o polos auxiliares) en una máquina de corriente continua?", opciones: ["Polos adicionales que mejoran la conmutación reduciendo el chispeo en las escobillas", "Los polos principales encargados de crear el campo magnético inductor", "Un tipo de escobilla especial de mayor tamaño", "Un elemento exclusivo del colector de delgas"], correctaTexto: "Polos adicionales que mejoran la conmutación reduciendo el chispeo en las escobillas", explicacion: "Los polos de conmutación son polos auxiliares, situados entre los polos principales, que mejoran el proceso de conmutación en el colector, reduciendo el chispeo en las escobillas." },
  { id: 800612, tema: "U6: Máquinas de corriente continua y sus bobinados (TEST OFICIAL)", texto: "¿Qué tipo de bobinado del inducido conecta las bobinas de forma que se avanza progresivamente alrededor del inducido, cerrando el circuito tras recorrerlo completo?", opciones: ["Bobinado ondulado (o en onda)", "Bobinado imbricado (o en paralelo)", "Bobinado concéntrico", "Bobinado excéntrico"], correctaTexto: "Bobinado ondulado (o en onda)", explicacion: "En el bobinado ondulado (o en onda), las bobinas se conectan avanzando progresivamente alrededor del inducido, cerrando el circuito completo tras recorrerlo entero, siendo habitual en máquinas de tensión elevada." },
  { id: 800613, tema: "U6: Máquinas de corriente continua y sus bobinados (TEST OFICIAL)", texto: "¿Qué tipo de bobinado del inducido conecta las bobinas de forma que quedan agrupadas en varios circuitos en paralelo?", opciones: ["Bobinado imbricado (o en paralelo)", "Bobinado ondulado (o en onda)", "Bobinado concéntrico", "Bobinado toroidal"], correctaTexto: "Bobinado imbricado (o en paralelo)", explicacion: "En el bobinado imbricado (o en paralelo), las bobinas quedan agrupadas en varios circuitos en paralelo, siendo habitual en máquinas de gran intensidad y baja tensión." },
  { id: 800614, tema: "U6: Máquinas de corriente continua y sus bobinados (TEST OFICIAL)", texto: "¿Qué precaución constructiva se adopta al fabricar el núcleo del inducido de una máquina de corriente continua?", opciones: ["Laminar el núcleo en chapas magnéticas aisladas para reducir las corrientes de Foucault", "Fabricar el núcleo completamente macizo sin ninguna laminación", "Utilizar exclusivamente cobre macizo en el núcleo", "Prescindir por completo de cualquier material ferromagnético"], correctaTexto: "Laminar el núcleo en chapas magnéticas aisladas para reducir las corrientes de Foucault", explicacion: "El núcleo del inducido de una máquina de corriente continua, al girar dentro de un campo magnético, se lamina en chapas magnéticas aisladas entre sí para reducir las pérdidas por corrientes de Foucault." },
  { id: 800615, tema: "U6: Máquinas de corriente continua y sus bobinados (TEST OFICIAL)", texto: "¿Qué elemento mecánico soporta el conjunto del rotor y le permite girar sobre su eje con el menor rozamiento posible?", opciones: ["Los rodamientos o cojinetes", "El colector de delgas", "Las escobillas", "Las piezas polares"], correctaTexto: "Los rodamientos o cojinetes", explicacion: "Los rodamientos o cojinetes soportan el eje del rotor, permitiéndole girar con el mínimo rozamiento posible y garantizando un correcto alineamiento mecánico de la máquina." },
  { id: 800616, tema: "U6: Máquinas de corriente continua y sus bobinados (TEST OFICIAL)", texto: "¿Qué es la reacción de inducido en una máquina de corriente continua?", opciones: ["La distorsión del campo magnético principal producida por el propio campo magnético generado por la corriente del inducido", "Un fenómeno exclusivo de las máquinas en vacío sin carga alguna", "La reacción mecánica del eje frente a un esfuerzo de torsión", "Un tipo de bobinado especial del inductor"], correctaTexto: "La distorsión del campo magnético principal producida por el propio campo magnético generado por la corriente del inducido", explicacion: "La reacción de inducido es la distorsión que sufre el campo magnético principal (creado por el inductor) debido al campo magnético generado por la propia corriente que circula por el inducido bajo carga." },
  { id: 800617, tema: "U6: Máquinas de corriente continua y sus bobinados (TEST OFICIAL)", texto: "¿Qué es la conmutación en una máquina de corriente continua?", opciones: ["El proceso mediante el cual el colector de delgas y las escobillas transforman la corriente alterna generada en el inducido en corriente continua en el circuito exterior", "El proceso de conexión inicial de la máquina a la red eléctrica", "Un tipo de ensayo eléctrico realizado únicamente en transformadores", "El proceso de enfriamiento del bobinado inductor"], correctaTexto: "El proceso mediante el cual el colector de delgas y las escobillas transforman la corriente alterna generada en el inducido en corriente continua en el circuito exterior", explicacion: "La conmutación es el proceso por el cual el colector de delgas, junto con las escobillas, transforma la corriente alterna generada internamente en el inducido en una corriente continua en el circuito exterior de la máquina." },
  { id: 800618, tema: "U6: Máquinas de corriente continua y sus bobinados (TEST OFICIAL)", texto: "¿Qué material aislante se emplea habitualmente entre las delgas del colector de una máquina de corriente continua?", opciones: ["La mica", "El cobre puro", "El grafito", "El acero al silicio"], correctaTexto: "La mica", explicacion: "La mica es el material aislante habitualmente empleado entre las delgas del colector, gracias a su elevada resistencia dieléctrica y estabilidad térmica." },
  { id: 800619, tema: "U6: Máquinas de corriente continua y sus bobinados (TEST OFICIAL)", texto: "¿Qué elemento regula la presión de las escobillas sobre el colector, garantizando un contacto eléctrico adecuado?", opciones: ["El portaescobillas con su resorte de presión", "El bobinado de excitación", "El entrehierro de la máquina", "El eje del rotor"], correctaTexto: "El portaescobillas con su resorte de presión", explicacion: "El portaescobillas, dotado de un resorte de presión, mantiene a la escobilla en contacto adecuado con el colector, garantizando una correcta transmisión eléctrica durante el giro de la máquina." },
  { id: 800620, tema: "U6: Máquinas de corriente continua y sus bobinados (TEST OFICIAL)", texto: "¿Qué consecuencia tiene un desgaste excesivo de las escobillas en una máquina de corriente continua?", opciones: ["Pérdida de contacto eléctrico, chispeo excesivo y posible daño al colector", "Una mejora automática del rendimiento de la máquina", "Ningún efecto relevante sobre el funcionamiento de la máquina", "Un aumento de la velocidad de giro del rotor"], correctaTexto: "Pérdida de contacto eléctrico, chispeo excesivo y posible daño al colector", explicacion: "El desgaste excesivo de las escobillas provoca pérdida de contacto eléctrico con el colector, aumento del chispeo y, si no se corrige a tiempo, puede llegar a dañar la superficie del propio colector." }
];

const TEMA_MAQUINAS_U7_DATA = [
  { id: 800701, tema: "U7: Mantenimiento y reparación de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Cada cuántas horas de trabajo se establecen habitualmente las revisiones de mantenimiento preventivo en máquinas de c.c.?", opciones: ["Entre 1.500 y 2.000 horas", "Entre 100 y 200 horas", "Entre 10.000 y 20.000 horas", "Cada 24 horas"], correctaTexto: "Entre 1.500 y 2.000 horas", explicacion: "Se deben establecer programas de mantenimiento preventivo para un número de horas de trabajo entre un rango de 1.500 y 2.000 horas." },
  { id: 800702, tema: "U7: Mantenimiento y reparación de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué señal indica que hay un cortocircuito en el inducido de una máquina de c.c.?", opciones: ["La máquina no gira o gira lenta, se calienta en exceso y huele a quemado", "La máquina gira más rápido de lo normal sin calentarse", "No hay ningún cambio perceptible", "El colector se vuelve más brillante"], correctaTexto: "La máquina no gira o gira lenta, se calienta en exceso y huele a quemado", explicacion: "Si la máquina no gira o lo hace muy lentamente, se calienta en exceso y huele a quemado, es señal de cortocircuito en el inducido." },
  { id: 800703, tema: "U7: Mantenimiento y reparación de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué proceso consiste en la fijación firme de las conexiones que van hacia el colector y asegurar las bobinas en las ranuras?", opciones: ["El zunchado del inducido", "El barnizado", "El equilibrado mecánico", "El torneado del colector"], correctaTexto: "El zunchado del inducido", explicacion: "El zunchado consiste en la fijación firme de las conexiones que van hacia el colector y en asegurar las bobinas en las ranuras." },
  { id: 800704, tema: "U7: Mantenimiento y reparación de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué operación de mantenimiento se realiza sobre el colector de delgas cuando presenta desgaste irregular o rugosidad excesiva?", opciones: ["El rectificado o torneado del colector", "La sustitución completa del núcleo del inducido", "El rebobinado íntegro del inductor", "La sustitución del eje del rotor"], correctaTexto: "El rectificado o torneado del colector", explicacion: "Cuando el colector presenta desgaste irregular o rugosidad excesiva, se realiza un rectificado o torneado de su superficie para restaurar una superficie de contacto uniforme para las escobillas." },
  { id: 800705, tema: "U7: Mantenimiento y reparación de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué operación se realiza tras el torneado del colector para eliminar el material que pueda haber quedado entre las delgas?", opciones: ["El rebaje o socavado de la mica entre delgas", "El zunchado del inducido", "La impregnación con barniz", "El equilibrado dinámico del rotor"], correctaTexto: "El rebaje o socavado de la mica entre delgas", explicacion: "Tras el torneado del colector se realiza el rebaje o socavado de la mica entre delgas, ya que esta no se desgasta igual que el cobre, pudiendo quedar sobresaliente y afectar al contacto de las escobillas." },
  { id: 800706, tema: "U7: Mantenimiento y reparación de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué prueba permite detectar una espira en cortocircuito dentro del bobinado del inducido?", opciones: ["El ensayo con el crecogrowler (detector de cortocircuitos de inducidos)", "La medición exclusiva de la velocidad de giro", "La comprobación visual del color de la carcasa", "El ensayo de rigidez dieléctrica del aceite"], correctaTexto: "El ensayo con el crecogrowler (detector de cortocircuitos de inducidos)", explicacion: "El crecogrowler (o growler) es un equipo específico que permite detectar espiras en cortocircuito dentro del bobinado del inducido de una máquina de corriente continua." },
  { id: 800707, tema: "U7: Mantenimiento y reparación de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué operación de mantenimiento preventivo se recomienda realizar periódicamente sobre las escobillas de una máquina de c.c.?", opciones: ["Verificar su desgaste y sustituirlas cuando alcancen el límite mínimo indicado por el fabricante", "No requieren ningún tipo de revisión periódica", "Sustituirlas diariamente independientemente de su estado", "Aumentar la presión del portaescobillas al máximo posible sin ningún límite"], correctaTexto: "Verificar su desgaste y sustituirlas cuando alcancen el límite mínimo indicado por el fabricante", explicacion: "Las escobillas deben revisarse periódicamente, verificando su grado de desgaste y sustituyéndolas cuando alcanzan el límite mínimo indicado por el fabricante, para garantizar un correcto contacto con el colector." },
  { id: 800708, tema: "U7: Mantenimiento y reparación de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué causa habitual provoca un chispeo excesivo en las escobillas de una máquina de c.c. en funcionamiento?", opciones: ["Una mala calibración de la posición de las escobillas o un colector en mal estado", "Un exceso de lubricación en los rodamientos", "Un exceso de ventilación de la máquina", "Una tensión de alimentación excesivamente baja sin ninguna otra causa"], correctaTexto: "Una mala calibración de la posición de las escobillas o un colector en mal estado", explicacion: "El chispeo excesivo en las escobillas suele deberse a una mala calibración de su posición respecto a la línea neutra, o a un colector en mal estado (rugoso, ovalado o con delgas salientes)." },
  { id: 800709, tema: "U7: Mantenimiento y reparación de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué proceso se sigue para localizar una bobina abierta (interrupción) dentro del devanado del inducido?", opciones: ["Comprobar la continuidad eléctrica entre delgas consecutivas con un óhmetro o el propio growler", "Medir exclusivamente la velocidad de giro del rotor", "Comprobar únicamente el color del bobinado", "Aplicar tensión nominal directamente sin ninguna comprobación previa"], correctaTexto: "Comprobar la continuidad eléctrica entre delgas consecutivas con un óhmetro o el propio growler", explicacion: "Para localizar una bobina abierta se comprueba la continuidad eléctrica entre delgas consecutivas del colector utilizando un óhmetro o el propio equipo growler, detectando el punto donde se interrumpe el circuito." },
  { id: 800710, tema: "U7: Mantenimiento y reparación de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué se debe verificar al realizar el mantenimiento de los rodamientos de una máquina de corriente continua?", opciones: ["El nivel de lubricación, ausencia de ruido anómalo y holguras excesivas", "Únicamente el color de la grasa lubricante sin ninguna otra comprobación", "El desgaste de las escobillas exclusivamente", "El estado del bobinado inductor exclusivamente"], correctaTexto: "El nivel de lubricación, ausencia de ruido anómalo y holguras excesivas", explicacion: "El mantenimiento de los rodamientos debe verificar su correcto nivel de lubricación, la ausencia de ruidos anómalos durante el giro y que no existan holguras excesivas que puedan indicar desgaste." },
  { id: 800711, tema: "U7: Mantenimiento y reparación de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué es un contacto a masa en el bobinado de una máquina de corriente continua y cómo se detecta?", opciones: ["Una unión eléctrica indeseada entre el bobinado y la carcasa, detectable mediante megóhmetro", "Un tipo de conexión normal y deseada del circuito de excitación", "Una avería que solo puede detectarse desmontando completamente la máquina", "Un fenómeno que no afecta a la seguridad de la máquina"], correctaTexto: "Una unión eléctrica indeseada entre el bobinado y la carcasa, detectable mediante megóhmetro", explicacion: "Un contacto a masa es una unión eléctrica indeseada entre el bobinado y la carcasa metálica de la máquina, que se detecta midiendo la resistencia de aislamiento entre ambos con un megóhmetro." },
  { id: 800712, tema: "U7: Mantenimiento y reparación de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué se debe hacer si, tras la reparación de un inducido, se detecta un desequilibrio mecánico al girar?", opciones: ["Realizar un equilibrado dinámico del rotor añadiendo o retirando masa según sea necesario", "Ignorar el desequilibrio si la máquina sigue girando", "Aumentar la velocidad de giro para compensar el desequilibrio", "Sustituir únicamente las escobillas sin actuar sobre el rotor"], correctaTexto: "Realizar un equilibrado dinámico del rotor añadiendo o retirando masa según sea necesario", explicacion: "Ante un desequilibrio mecánico detectado tras una reparación, se debe realizar un equilibrado dinámico del rotor, añadiendo o retirando masa en los puntos necesarios hasta corregir la vibración." },
  { id: 800713, tema: "U7: Mantenimiento y reparación de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué se debe comprobar antes de volver a poner en servicio una máquina de corriente continua tras una reparación de su bobinado?", opciones: ["La resistencia de aislamiento, la continuidad del bobinado y la ausencia de cortocircuitos", "Únicamente el aspecto estético de la carcasa", "El color del barniz aplicado sin ninguna comprobación eléctrica", "Nada, se puede conectar directamente sin verificación previa"], correctaTexto: "La resistencia de aislamiento, la continuidad del bobinado y la ausencia de cortocircuitos", explicacion: "Tras reparar el bobinado de una máquina de corriente continua deben verificarse la resistencia de aislamiento, la continuidad eléctrica del devanado y la ausencia de cortocircuitos antes de su puesta en servicio." },
  { id: 800714, tema: "U7: Mantenimiento y reparación de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué registro documental es recomendable mantener actualizado para el seguimiento del mantenimiento de una máquina de corriente continua?", opciones: ["El historial o ficha de mantenimiento de la máquina", "Ningún registro es necesario", "Solo la factura de compra original de la máquina", "El manual de instrucciones genérico sin anotaciones propias"], correctaTexto: "El historial o ficha de mantenimiento de la máquina", explicacion: "El historial o ficha de mantenimiento permite registrar todas las intervenciones realizadas sobre la máquina, facilitando el seguimiento de su estado y la planificación de futuras revisiones." },
  { id: 800715, tema: "U7: Mantenimiento y reparación de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué medida de seguridad debe adoptarse siempre antes de intervenir sobre una máquina de corriente continua conectada a una instalación?", opciones: ["Desconectar la alimentación, bloquear el arranque y verificar la ausencia de tensión", "Trabajar directamente con la máquina en marcha para diagnosticar mejor la avería", "Ignorar cualquier medida de bloqueo si la intervención es breve", "Confiar en que la máquina está parada sin verificarlo"], correctaTexto: "Desconectar la alimentación, bloquear el arranque y verificar la ausencia de tensión", explicacion: "Antes de cualquier intervención sobre una máquina de corriente continua debe desconectarse su alimentación, bloquearse su posible arranque accidental y verificarse la ausencia de tensión, siguiendo las normas de seguridad eléctrica." },
  { id: 800716, tema: "U7: Mantenimiento y reparación de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué efecto puede tener la acumulación de polvo de carbón (procedente del desgaste de las escobillas) en el interior de la máquina?", opciones: ["Puede provocar fugas de corriente y reducir la resistencia de aislamiento entre partes activas", "Mejora la refrigeración interna de la máquina sin ningún riesgo", "No tiene ningún efecto sobre el funcionamiento eléctrico de la máquina", "Aumenta automáticamente el rendimiento de la máquina"], correctaTexto: "Puede provocar fugas de corriente y reducir la resistencia de aislamiento entre partes activas", explicacion: "El polvo de carbón acumulado, al ser conductor, puede provocar fugas de corriente entre partes activas y masa, reduciendo la resistencia de aislamiento de la máquina, por lo que debe eliminarse en el mantenimiento periódico." },
  { id: 800717, tema: "U7: Mantenimiento y reparación de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué comprobación se debe realizar sobre las conexiones eléctricas de una máquina de corriente continua durante su mantenimiento periódico?", opciones: ["Verificar el correcto apriete de bornes y ausencia de puntos calientes u oxidación", "Ninguna comprobación es necesaria si la máquina funciona aparentemente bien", "Solo verificar el color de los cables de conexión", "Sustituir todas las conexiones cada mes independientemente de su estado"], correctaTexto: "Verificar el correcto apriete de bornes y ausencia de puntos calientes u oxidación", explicacion: "El mantenimiento periódico debe incluir la verificación del correcto apriete de los bornes de conexión y la ausencia de puntos calientes u oxidación, que podrían indicar un mal contacto eléctrico." },
  { id: 800718, tema: "U7: Mantenimiento y reparación de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué medida se debe adoptar cuando el colector de una máquina de c.c. presenta delgas sueltas o levantadas?", opciones: ["Retirar la máquina de servicio y proceder a la reparación o sustitución del colector", "Continuar utilizando la máquina sin ninguna limitación mientras siga girando", "Aumentar la presión de las escobillas para compensar el problema", "Ignorar el problema si el chispeo no es muy visible"], correctaTexto: "Retirar la máquina de servicio y proceder a la reparación o sustitución del colector", explicacion: "Ante delgas sueltas o levantadas en el colector, la máquina debe retirarse de servicio para reparar o sustituir el colector, ya que continuar su uso puede provocar daños graves y riesgos de seguridad." },
  { id: 800719, tema: "U7: Mantenimiento y reparación de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué finalidad tiene la impregnación con barniz tras el rebobinado de una máquina de corriente continua?", opciones: ["Proteger el nuevo bobinado frente a la humedad y mejorar su rigidez dieléctrica y resistencia mecánica", "Mejorar exclusivamente el aspecto estético del bobinado", "Sustituir la función de las escobillas", "Aumentar el peso de la máquina sin ningún beneficio técnico"], correctaTexto: "Proteger el nuevo bobinado frente a la humedad y mejorar su rigidez dieléctrica y resistencia mecánica", explicacion: "Tras el rebobinado, la impregnación con barniz protege el nuevo devanado frente a la humedad, mejora su rigidez dieléctrica y aumenta su resistencia mecánica frente a vibraciones." },
  { id: 800720, tema: "U7: Mantenimiento y reparación de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué prueba final se recomienda realizar tras completar la reparación integral de una máquina de corriente continua?", opciones: ["Una prueba de funcionamiento en vacío seguida de una prueba progresiva bajo carga, verificando parámetros eléctricos y mecánicos", "Conectar la máquina directamente a su carga máxima sin ninguna prueba previa", "No es necesaria ninguna prueba si la reparación se ha realizado correctamente", "Solo verificar el aspecto estético final de la máquina"], correctaTexto: "Una prueba de funcionamiento en vacío seguida de una prueba progresiva bajo carga, verificando parámetros eléctricos y mecánicos", explicacion: "Tras una reparación integral se recomienda realizar primero una prueba de funcionamiento en vacío y, posteriormente, una prueba progresiva bajo carga, verificando en todo momento los parámetros eléctricos y mecánicos de la máquina." }
];

const TEMA_MAQUINAS_U8_DATA = [
  { id: 800801, tema: "U8: Ensayos de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué condiciones deben cumplirse para que una dinamo genere fuerza electromotriz?", opciones: ["Que exista flujo inductor y que gire el inducido en el seno del flujo", "Que la máquina esté en cortocircuito", "Que no circule corriente por el inductor", "Que el rotor esté parado"], correctaTexto: "Que exista flujo inductor y que gire el inducido en el seno del flujo", explicacion: "Una dinamo generará fuerza electromotriz si existe flujo inductor (corriente continua en los polos) y si gira el inducido en el seno de dicho flujo." },
  { id: 800802, tema: "U8: Ensayos de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué se necesita para que se produzca el cebado en una dinamo autoexcitada?", opciones: ["Que las masas polares tengan magnetismo remanente y la corriente refuerce ese magnetismo", "Que el inducido esté en cortocircuito permanente", "Que no exista ningún tipo de resistencia", "Que la velocidad sea nula"], correctaTexto: "Que las masas polares tengan magnetismo remanente y la corriente refuerce ese magnetismo", explicacion: "Para que el cebado se lleve a cabo, la corriente en las bobinas inductoras debe ser de un sentido que refuerce el magnetismo remanente de las masas polares." },
  { id: 800803, tema: "U8: Ensayos de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Cómo se denomina la máquina cuyo bobinado de excitación principal se conecta en paralelo con el circuito exterior?", opciones: ["Dinamo de excitación shunt", "Dinamo de excitación serie", "Dinamo de excitación independiente", "Dinamo compound"], correctaTexto: "Dinamo de excitación shunt", explicacion: "La máquina cuyo bobinado de excitación principal se conecta en paralelo con el circuito exterior se denomina dinamo de excitación shunt o paralelo." },
  { id: 800804, tema: "U8: Ensayos de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué ensayo permite obtener la característica en vacío de una dinamo (relación entre f.e.m. generada y corriente de excitación)?", opciones: ["El ensayo en vacío a velocidad constante variando la corriente de excitación", "El ensayo de cortocircuito exclusivamente", "El ensayo de resistencia de aislamiento exclusivamente", "El ensayo de calentamiento exclusivamente"], correctaTexto: "El ensayo en vacío a velocidad constante variando la corriente de excitación", explicacion: "El ensayo en vacío a velocidad constante, variando progresivamente la corriente de excitación y midiendo la f.e.m. generada, permite obtener la característica en vacío de la dinamo." },
  { id: 800805, tema: "U8: Ensayos de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué es la 'curva de carga' de un generador de corriente continua?", opciones: ["La representación gráfica de la tensión en bornes frente a la corriente de carga entregada", "La representación de la velocidad de giro frente al tiempo", "La representación de la resistencia de aislamiento frente a la temperatura", "La representación del par motor frente a la corriente de excitación"], correctaTexto: "La representación gráfica de la tensión en bornes frente a la corriente de carga entregada", explicacion: "La curva de carga de un generador de corriente continua representa gráficamente cómo varía la tensión en bornes a medida que aumenta la corriente de carga entregada al circuito exterior." },
  { id: 800806, tema: "U8: Ensayos de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué parámetro se determina mediante el ensayo de par-velocidad en un motor de corriente continua?", opciones: ["La relación entre el par motor desarrollado y la velocidad de giro a distintas condiciones de carga", "Únicamente la resistencia de aislamiento del bobinado", "El nivel de ruido acústico de la máquina", "La temperatura ambiente del taller"], correctaTexto: "La relación entre el par motor desarrollado y la velocidad de giro a distintas condiciones de carga", explicacion: "El ensayo de par-velocidad permite obtener la relación entre el par motor desarrollado por la máquina y su velocidad de giro bajo distintas condiciones de carga, siendo fundamental para caracterizar un motor de c.c." },
  { id: 800807, tema: "U8: Ensayos de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué método se emplea habitualmente para determinar el rendimiento de una máquina de corriente continua de gran potencia sin necesidad de aplicarle su carga nominal completa?", opciones: ["El método de pérdidas separadas", "La medición directa exclusivamente con la carga nominal aplicada físicamente", "El ensayo de rigidez dieléctrica exclusivamente", "La medición exclusiva de la velocidad de giro en vacío"], correctaTexto: "El método de pérdidas separadas", explicacion: "El método de pérdidas separadas permite determinar el rendimiento de una máquina de gran potencia sumando las distintas pérdidas (mecánicas, en el hierro, en el cobre) obtenidas mediante ensayos parciales, sin necesidad de aplicar la carga nominal completa." },
  { id: 800808, tema: "U8: Ensayos de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué pérdidas mecánicas se determinan mediante el ensayo en vacío de un motor de corriente continua girando a su velocidad nominal sin carga?", opciones: ["Las pérdidas por rozamiento en los rodamientos y por resistencia del aire (ventilación)", "Las pérdidas exclusivamente en el bobinado inductor", "Las pérdidas exclusivamente en el aislamiento del colector", "Las pérdidas por corrientes de Foucault en el estator"], correctaTexto: "Las pérdidas por rozamiento en los rodamientos y por resistencia del aire (ventilación)", explicacion: "El ensayo en vacío de un motor girando a su velocidad nominal permite determinar las pérdidas mecánicas, que incluyen el rozamiento en los rodamientos y las escobillas, y la resistencia del aire durante la ventilación." },
  { id: 800809, tema: "U8: Ensayos de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué relación existe entre la velocidad de giro de un motor shunt de corriente continua y la corriente de excitación, manteniendo constante la tensión de alimentación?", opciones: ["A mayor corriente de excitación, menor velocidad de giro del motor", "A mayor corriente de excitación, mayor velocidad de giro del motor de forma proporcional siempre", "La velocidad de giro es totalmente independiente de la corriente de excitación", "La corriente de excitación no tiene ninguna influencia sobre la velocidad"], correctaTexto: "A mayor corriente de excitación, menor velocidad de giro del motor", explicacion: "En un motor shunt de corriente continua, para una tensión de alimentación constante, un aumento de la corriente de excitación provoca una disminución de la velocidad de giro del motor, dada la relación inversa entre flujo y velocidad." },
  { id: 800810, tema: "U8: Ensayos de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué instrumento se utiliza para medir el par motor desarrollado por una máquina de corriente continua durante un ensayo?", opciones: ["El freno dinamométrico o torquímetro", "El megóhmetro", "El tacómetro exclusivamente sin ningún otro instrumento", "El calibre de precisión"], correctaTexto: "El freno dinamométrico o torquímetro", explicacion: "El freno dinamométrico (o torquímetro) es el instrumento empleado para medir directamente el par motor desarrollado por una máquina durante los ensayos de caracterización." },
  { id: 800811, tema: "U8: Ensayos de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué es el 'ensayo de embalamiento' en un motor de corriente continua y por qué es importante conocerlo?", opciones: ["El ensayo que determina la velocidad máxima teórica alcanzable si se pierde la excitación del motor shunt en carga ligera", "Un ensayo exclusivo de los generadores en cortocircuito", "Un ensayo que mide únicamente la resistencia de aislamiento", "Un ensayo que se realiza exclusivamente en transformadores"], correctaTexto: "El ensayo que determina la velocidad máxima teórica alcanzable si se pierde la excitación del motor shunt en carga ligera", explicacion: "El ensayo (o análisis) de embalamiento estudia la velocidad máxima teórica que podría alcanzar un motor shunt si perdiera la excitación estando en carga ligera, fenómeno peligroso que debe preverse en el diseño y protección de la máquina." },
  { id: 800812, tema: "U8: Ensayos de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué es la 'reacción de inducido' y cómo afecta a los resultados de los ensayos bajo carga de una dinamo?", opciones: ["Provoca una distorsión del campo magnético y una caída de tensión adicional que debe considerarse en los ensayos bajo carga", "No tiene ninguna influencia sobre los resultados obtenidos en los ensayos", "Solo afecta a los ensayos realizados en vacío, nunca bajo carga", "Mejora artificialmente el rendimiento medido durante el ensayo"], correctaTexto: "Provoca una distorsión del campo magnético y una caída de tensión adicional que debe considerarse en los ensayos bajo carga", explicacion: "La reacción de inducido provoca una distorsión del campo magnético principal y una caída de tensión adicional bajo carga, efectos que deben tenerse en cuenta al interpretar los resultados de los ensayos realizados con la máquina cargada." },
  { id: 800813, tema: "U8: Ensayos de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué parámetro permite calcular el rendimiento total de un motor de corriente continua a partir de la potencia eléctrica absorbida y la potencia mecánica entregada en el eje?", opciones: ["El cociente entre la potencia mecánica en el eje y la potencia eléctrica absorbida", "El cociente entre la resistencia del inducido y la del inductor", "La diferencia entre la tensión nominal y la tensión de vacío", "El producto entre la velocidad de giro y el par motor sin ninguna otra magnitud"], correctaTexto: "El cociente entre la potencia mecánica en el eje y la potencia eléctrica absorbida", explicacion: "El rendimiento total de un motor de corriente continua se obtiene mediante el cociente entre la potencia mecánica útil entregada en el eje y la potencia eléctrica total absorbida de la red." },
  { id: 800814, tema: "U8: Ensayos de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué precaución de seguridad es especialmente importante al ensayar un motor shunt de corriente continua en vacío o con carga muy ligera?", opciones: ["Asegurar que el circuito de excitación no quede abierto accidentalmente, evitando el riesgo de embalamiento", "No es necesaria ninguna precaución especial en este tipo de ensayo", "Aumentar al máximo la corriente de excitación sin ningún límite", "Desconectar completamente el bobinado inducido durante el ensayo"], correctaTexto: "Asegurar que el circuito de excitación no quede abierto accidentalmente, evitando el riesgo de embalamiento", explicacion: "Al ensayar un motor shunt en vacío o carga ligera es fundamental asegurar que el circuito de excitación no quede abierto accidentalmente, ya que esto podría provocar un peligroso embalamiento de la máquina." },
  { id: 800815, tema: "U8: Ensayos de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué magnitud se obtiene al dividir la fuerza electromotriz generada por una dinamo entre la velocidad angular de giro, para un flujo de excitación constante?", opciones: ["La constante de fuerza electromotriz de la máquina", "La resistencia interna del inducido", "La reluctancia del circuito magnético", "La reactancia de dispersión del devanado"], correctaTexto: "La constante de fuerza electromotriz de la máquina", explicacion: "El cociente entre la f.e.m. generada y la velocidad angular de giro, para un flujo de excitación constante, proporciona la constante de fuerza electromotriz característica de la máquina de corriente continua." },
  { id: 800816, tema: "U8: Ensayos de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué se entiende por 'característica externa' de un generador de corriente continua?", opciones: ["La relación entre la tensión en bornes y la corriente de carga, a velocidad y excitación constantes", "La relación entre la temperatura ambiente y el rendimiento de la máquina", "La relación entre el peso de la máquina y su potencia nominal", "La relación entre el número de delgas del colector y la potencia nominal"], correctaTexto: "La relación entre la tensión en bornes y la corriente de carga, a velocidad y excitación constantes", explicacion: "La característica externa de un generador de corriente continua muestra cómo varía la tensión en bornes en función de la corriente de carga entregada, manteniendo constantes la velocidad de giro y la excitación." },
  { id: 800817, tema: "U8: Ensayos de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué efecto tiene el aumento de temperatura del bobinado sobre la resistencia óhmica medida durante un ensayo?", opciones: ["La resistencia óhmica del cobre aumenta al aumentar la temperatura", "La resistencia óhmica del cobre disminuye al aumentar la temperatura", "La temperatura no influye en absoluto en la resistencia óhmica del cobre", "La resistencia óhmica se vuelve negativa a temperaturas elevadas"], correctaTexto: "La resistencia óhmica del cobre aumenta al aumentar la temperatura", explicacion: "La resistencia óhmica de los conductores de cobre aumenta con la temperatura, por lo que en los ensayos se debe corregir el valor medido a la temperatura de referencia normalizada para comparaciones fiables." },
  { id: 800818, tema: "U8: Ensayos de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué información aporta el ensayo de cortocircuito bajo excitación reducida en un generador de corriente continua?", opciones: ["Permite conocer la resistencia del circuito del inducido y calcular pérdidas en el cobre bajo condiciones controladas", "Permite conocer exclusivamente la velocidad máxima de la máquina", "Permite conocer exclusivamente el peso total de la máquina", "No aporta ninguna información técnica relevante"], correctaTexto: "Permite conocer la resistencia del circuito del inducido y calcular pérdidas en el cobre bajo condiciones controladas", explicacion: "El ensayo de cortocircuito con excitación reducida permite conocer la resistencia del circuito del inducido y calcular las pérdidas en el cobre bajo condiciones controladas, evitando corrientes excesivas y peligrosas." },
  { id: 800819, tema: "U8: Ensayos de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué finalidad tiene comparar los resultados de los ensayos periódicos de una máquina con los valores obtenidos en su puesta en marcha inicial?", opciones: ["Detectar tendencias de deterioro progresivo y anticiparse a posibles averías", "No tiene ninguna finalidad práctica relevante", "Sirve exclusivamente para justificar la garantía comercial del fabricante", "Permite aumentar automáticamente la potencia nominal de la máquina"], correctaTexto: "Detectar tendencias de deterioro progresivo y anticiparse a posibles averías", explicacion: "Comparar los resultados de ensayos periódicos con los valores iniciales de puesta en marcha permite detectar tendencias de deterioro progresivo en la máquina, anticipándose a posibles averías mediante un mantenimiento predictivo eficaz." },
  { id: 800820, tema: "U8: Ensayos de máquinas eléctricas de corriente continua (TEST OFICIAL)", texto: "¿Qué normativa técnica establece los procedimientos normalizados para la realización de ensayos en máquinas eléctricas rotativas?", opciones: ["Las normas de la serie IEC 60034", "El Reglamento Electrotécnico de Baja Tensión exclusivamente", "El Código Técnico de la Edificación exclusivamente", "La Ley de Prevención de Riesgos Laborales exclusivamente"], correctaTexto: "Las normas de la serie IEC 60034", explicacion: "Las normas de la serie IEC 60034 establecen los procedimientos normalizados internacionalmente reconocidos para la realización de ensayos y determinación de características en máquinas eléctricas rotativas." }
];

const TEMA_MAQUINAS_U9_DATA = [
  { id: 800901, tema: "U9: Máquinas de corriente alterna y sus bobinados (TEST OFICIAL)", texto: "¿Qué elemento del alternador está formado por chapas apiladas y troqueladas donde se ubica el circuito inducido?", opciones: ["El estator", "El rotor", "El colector de anillos", "La excitatriz"], correctaTexto: "El estator", explicacion: "El estator, parte fija, está constituido por chapas apiladas y troqueladas formando ranuras donde se sitúa el circuito inducido." },
  { id: 800902, tema: "U9: Máquinas de corriente alterna y sus bobinados (TEST OFICIAL)", texto: "¿Cuántos grados eléctricos separan los tres grupos de bobinas de un bobinado trifásico?", opciones: ["120º eléctricos", "90º eléctricos", "60º eléctricos", "180º eléctricos"], correctaTexto: "120º eléctricos", explicacion: "Los bobinados trifásicos están formados por tres grupos de bobinas separados 120º eléctricos entre sí, alimentados por un sistema trifásico." },
  { id: 800903, tema: "U9: Máquinas de corriente alterna y sus bobinados (TEST OFICIAL)", texto: "¿Cómo se denominan los bobinados constituidos por bobinas de distinta amplitud de modo que cada una rodea a la siguiente?", opciones: ["Bobinados concéntricos", "Bobinados excéntricos", "Bobinados separados", "Bobinados ondulados"], correctaTexto: "Bobinados concéntricos", explicacion: "Los bobinados concéntricos están constituidos por bobinas de distinta amplitud de modo que cada una rodea a la siguiente." },
  { id: 800904, tema: "U9: Máquinas de corriente alterna y sus bobinados (TEST OFICIAL)", texto: "¿Qué es el rotor de un motor asíncrono tipo jaula de ardilla?", opciones: ["Un rotor formado por barras conductoras cortocircuitadas en sus extremos por anillos, sin bobinado propiamente dicho", "Un rotor bobinado con conexión a anillos rozantes y reóstato exterior", "Un rotor exclusivo de las máquinas de corriente continua", "Un rotor que no gira, solo el estator lo hace"], correctaTexto: "Un rotor formado por barras conductoras cortocircuitadas en sus extremos por anillos, sin bobinado propiamente dicho", explicacion: "El rotor de jaula de ardilla está formado por barras conductoras (habitualmente de aluminio o cobre) alojadas en el núcleo del rotor y cortocircuitadas en sus extremos por dos anillos, sin bobinado convencional." },
  { id: 800905, tema: "U9: Máquinas de corriente alterna y sus bobinados (TEST OFICIAL)", texto: "¿Qué es el rotor bobinado (o de anillos rozantes) en un motor asíncrono?", opciones: ["Un rotor con devanado trifásico conectado a anillos rozantes que permiten acceder externamente al circuito del rotor", "Un rotor sin ningún tipo de devanado, formado solo por barras conductoras", "Un rotor exclusivo de motores monofásicos de baja potencia", "Un tipo de rotor que solo se emplea en generadores de corriente continua"], correctaTexto: "Un rotor con devanado trifásico conectado a anillos rozantes que permiten acceder externamente al circuito del rotor", explicacion: "El rotor bobinado (o de anillos rozantes) dispone de un devanado trifásico conectado a tres anillos rozantes, que permiten conectar externamente resistencias u otros elementos para regular el arranque o la velocidad." },
  { id: 800906, tema: "U9: Máquinas de corriente alterna y sus bobinados (TEST OFICIAL)", texto: "¿Qué es el 'paso de bobina' en un devanado de máquina de corriente alterna?", opciones: ["La distancia, medida en ranuras, entre los dos lados activos de una misma bobina", "El número total de bobinas del devanado completo", "El diámetro del hilo de cobre utilizado en el bobinado", "La velocidad de giro nominal de la máquina"], correctaTexto: "La distancia, medida en ranuras, entre los dos lados activos de una misma bobina", explicacion: "El paso de bobina es la distancia, expresada en número de ranuras, que separa los dos lados activos de una misma bobina dentro del núcleo del estator o rotor." },
  { id: 800907, tema: "U9: Máquinas de corriente alterna y sus bobinados (TEST OFICIAL)", texto: "¿Qué diferencia existe entre un devanado de paso completo (diametral) y uno de paso acortado (fraccionario)?", opciones: ["El de paso completo abarca exactamente un paso polar; el de paso acortado abarca una fracción menor, mejorando la forma de onda de la f.e.m.", "El de paso acortado siempre genera mayor tensión que el de paso completo", "Ambos tipos de paso son exactamente equivalentes en todos los aspectos", "El paso acortado solo se emplea en máquinas de corriente continua"], correctaTexto: "El de paso completo abarca exactamente un paso polar; el de paso acortado abarca una fracción menor, mejorando la forma de onda de la f.e.m.", explicacion: "El devanado de paso completo (diametral) abarca exactamente un paso polar, mientras que el de paso acortado (fraccionario) abarca una fracción menor, lo que ayuda a reducir armónicos y mejorar la forma de onda de la f.e.m. generada." },
  { id: 800908, tema: "U9: Máquinas de corriente alterna y sus bobinados (TEST OFICIAL)", texto: "¿Qué es el número de polos de una máquina de corriente alterna y cómo influye en su velocidad de sincronismo?", opciones: ["Es el número de polos magnéticos del devanado; a mayor número de polos, menor velocidad de sincronismo para una misma frecuencia", "El número de polos no tiene ninguna relación con la velocidad de sincronismo", "A mayor número de polos, siempre mayor velocidad de sincronismo", "El número de polos determina exclusivamente la potencia nominal de la máquina"], correctaTexto: "Es el número de polos magnéticos del devanado; a mayor número de polos, menor velocidad de sincronismo para una misma frecuencia", explicacion: "El número de polos del devanado determina, junto con la frecuencia de la red, la velocidad de sincronismo de la máquina (n=60f/p), de modo que a mayor número de polos, menor es la velocidad de sincronismo." },
  { id: 800909, tema: "U9: Máquinas de corriente alterna y sus bobinados (TEST OFICIAL)", texto: "¿Qué es un devanado de doble capa en una máquina de corriente alterna?", opciones: ["Un devanado en el que cada ranura del núcleo aloja dos lados de bobina distintos", "Un devanado que utiliza el doble de espiras que un devanado convencional", "Un devanado exclusivo de las máquinas monofásicas", "Un tipo de devanado sin ningún aislamiento entre capas"], correctaTexto: "Un devanado en el que cada ranura del núcleo aloja dos lados de bobina distintos", explicacion: "En un devanado de doble capa, cada ranura del núcleo aloja dos lados de bobina diferentes (uno en la parte superior y otro en la inferior de la ranura), a diferencia del devanado de capa simple." },
  { id: 800910, tema: "U9: Máquinas de corriente alterna y sus bobinados (TEST OFICIAL)", texto: "¿Qué elemento del rotor bobinado permite conectar resistencias externas para reducir la corriente de arranque de un motor asíncrono?", opciones: ["Los anillos rozantes con sus escobillas correspondientes", "El colector de delgas", "La jaula de ardilla", "El entrehierro del rotor"], correctaTexto: "Los anillos rozantes con sus escobillas correspondientes", explicacion: "Los anillos rozantes, junto con sus escobillas correspondientes, permiten conectar resistencias externas al devanado del rotor bobinado, reduciendo así la corriente de arranque del motor asíncrono." },
  { id: 800911, tema: "U9: Máquinas de corriente alterna y sus bobinados (TEST OFICIAL)", texto: "¿Qué material se emplea habitualmente para fabricar las barras conductoras de un rotor de jaula de ardilla de pequeña y mediana potencia?", opciones: ["Aluminio inyectado a presión", "Cobre macizo laminado exclusivamente en todos los casos", "Plástico reforzado con fibra de vidrio", "Acero inoxidable macizo"], correctaTexto: "Aluminio inyectado a presión", explicacion: "En motores de jaula de ardilla de pequeña y mediana potencia, las barras conductoras y los anillos de cortocircuito se fabrican habitualmente mediante inyección de aluminio a presión en el núcleo del rotor." },
  { id: 800912, tema: "U9: Máquinas de corriente alterna y sus bobinados (TEST OFICIAL)", texto: "¿Qué es el factor de distribución (o factor de reparto) de un devanado de corriente alterna?", opciones: ["Un coeficiente que corrige la fuerza electromotriz teórica considerando que las bobinas de un grupo están distribuidas en varias ranuras", "Un coeficiente exclusivo del cálculo mecánico del rotor", "Un coeficiente que solo se aplica en máquinas de corriente continua", "Un coeficiente que determina el número de fases del sistema"], correctaTexto: "Un coeficiente que corrige la fuerza electromotriz teórica considerando que las bobinas de un grupo están distribuidas en varias ranuras", explicacion: "El factor de distribución corrige el cálculo de la fuerza electromotriz teórica, considerando que las bobinas de un mismo grupo no están concentradas en una única ranura sino distribuidas en varias, con el consiguiente desfase entre ellas." },
  { id: 800913, tema: "U9: Máquinas de corriente alterna y sus bobinados (TEST OFICIAL)", texto: "¿Qué es el factor de paso de un devanado de corriente alterna con paso acortado?", opciones: ["Un coeficiente que corrige la f.e.m. teórica debido a que el paso de bobina es menor que el paso polar completo", "Un coeficiente que mide exclusivamente el diámetro del hilo conductor", "Un coeficiente relacionado únicamente con la velocidad de giro del rotor", "Un coeficiente que determina el tipo de aislamiento térmico del bobinado"], correctaTexto: "Un coeficiente que corrige la f.e.m. teórica debido a que el paso de bobina es menor que el paso polar completo", explicacion: "El factor de paso corrige el cálculo de la fuerza electromotriz teórica cuando se emplea un devanado de paso acortado, en el que el paso de bobina es menor que el paso polar completo." },
  { id: 800914, tema: "U9: Máquinas de corriente alterna y sus bobinados (TEST OFICIAL)", texto: "¿Qué elemento del núcleo del estator aloja los conductores del devanado y proporciona el camino magnético?", opciones: ["Las ranuras practicadas sobre las chapas magnéticas apiladas", "El eje del rotor", "El colector de delgas", "Los anillos rozantes"], correctaTexto: "Las ranuras practicadas sobre las chapas magnéticas apiladas", explicacion: "Las ranuras, practicadas sobre las chapas magnéticas apiladas que forman el núcleo del estator, alojan los conductores del devanado y, junto al propio núcleo, proporcionan el camino magnético necesario." },
  { id: 800915, tema: "U9: Máquinas de corriente alterna y sus bobinados (TEST OFICIAL)", texto: "¿Qué diferencia fundamental existe entre el bobinado del estator de un motor asíncrono trifásico y el de uno monofásico?", opciones: ["El trifásico dispone de tres devanados desfasados 120º; el monofásico dispone de un único devanado principal (y a veces uno auxiliar de arranque)", "El monofásico siempre tiene mayor potencia que el trifásico", "Ambos bobinados son exactamente idénticos sin ninguna diferencia", "El trifásico no requiere ningún tipo de aislamiento entre fases"], correctaTexto: "El trifásico dispone de tres devanados desfasados 120º; el monofásico dispone de un único devanado principal (y a veces uno auxiliar de arranque)", explicacion: "El motor trifásico dispone de tres devanados desfasados 120º eléctricos entre sí, mientras que el motor monofásico dispone de un único devanado principal, pudiendo incorporar un devanado auxiliar de arranque desfasado mediante un condensador." },
  { id: 800916, tema: "U9: Máquinas de corriente alterna y sus bobinados (TEST OFICIAL)", texto: "¿Qué componente adicional incorpora habitualmente el devanado auxiliar de un motor monofásico de arranque por condensador?", opciones: ["Un condensador conectado en serie con el devanado auxiliar para generar el desfase necesario", "Un colector de delgas adicional", "Un segundo rotor de jaula de ardilla", "Un transformador de aislamiento independiente"], correctaTexto: "Un condensador conectado en serie con el devanado auxiliar para generar el desfase necesario", explicacion: "En los motores monofásicos de arranque por condensador, este se conecta en serie con el devanado auxiliar, generando el desfase eléctrico necesario para crear el campo magnético giratorio de arranque." },
  { id: 800917, tema: "U9: Máquinas de corriente alterna y sus bobinados (TEST OFICIAL)", texto: "¿Qué es la 'conexión en estrella' de un devanado trifásico?", opciones: ["Una conexión en la que un extremo de cada fase se une en un punto común (neutro) y el otro extremo queda libre para la alimentación", "Una conexión en la que todas las fases quedan completamente independientes sin ningún punto común", "Una conexión exclusiva de los devanados monofásicos", "Una conexión que solo puede realizarse en máquinas de corriente continua"], correctaTexto: "Una conexión en la que un extremo de cada fase se une en un punto común (neutro) y el otro extremo queda libre para la alimentación", explicacion: "En la conexión en estrella, un extremo de cada uno de los tres devanados se une en un punto común (neutro), quedando el otro extremo de cada fase disponible para la conexión a la red de alimentación." },
  { id: 800918, tema: "U9: Máquinas de corriente alterna y sus bobinados (TEST OFICIAL)", texto: "¿Qué es la 'conexión en triángulo' de un devanado trifásico?", opciones: ["Una conexión en la que el final de cada fase se une al principio de la siguiente, formando un circuito cerrado sin punto neutro", "Una conexión idéntica a la conexión en estrella sin ninguna diferencia", "Una conexión exclusiva de los devanados de corriente continua", "Una conexión en la que las tres fases quedan totalmente aisladas entre sí"], correctaTexto: "Una conexión en la que el final de cada fase se une al principio de la siguiente, formando un circuito cerrado sin punto neutro", explicacion: "En la conexión en triángulo, el final de cada devanado se conecta al principio del siguiente, formando un circuito cerrado sin punto neutro disponible, a diferencia de la conexión en estrella." },
  { id: 800919, tema: "U9: Máquinas de corriente alterna y sus bobinados (TEST OFICIAL)", texto: "¿Qué relación existe entre la tensión de línea y la tensión de fase en una conexión en estrella equilibrada?", opciones: ["La tensión de línea es √3 veces mayor que la tensión de fase", "La tensión de línea es igual a la tensión de fase", "La tensión de línea es la mitad de la tensión de fase", "La tensión de línea es el triple de la tensión de fase"], correctaTexto: "La tensión de línea es √3 veces mayor que la tensión de fase", explicacion: "En una conexión en estrella equilibrada, la tensión de línea (entre dos fases) es √3 (aproximadamente 1,73) veces mayor que la tensión de fase (entre una fase y el neutro)." },
  { id: 800920, tema: "U9: Máquinas de corriente alterna y sus bobinados (TEST OFICIAL)", texto: "¿Qué es el deslizamiento en un motor asíncrono trifásico?", opciones: ["La diferencia relativa entre la velocidad de sincronismo del campo giratorio y la velocidad real de giro del rotor", "La diferencia de tensión entre el estator y el rotor", "El desgaste mecánico acumulado en los rodamientos del motor", "La diferencia entre la potencia nominal y la potencia real absorbida"], correctaTexto: "La diferencia relativa entre la velocidad de sincronismo del campo giratorio y la velocidad real de giro del rotor", explicacion: "El deslizamiento es la diferencia relativa, expresada habitualmente en tanto por ciento, entre la velocidad de sincronismo del campo magnético giratorio del estator y la velocidad real de giro del rotor del motor asíncrono." }
];

const TEMA_MAQUINAS_U10_DATA = [
  { id: 801001, tema: "U10: Mantenimiento y reparación de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Cómo se denomina la unión eléctrica indeseada entre el devanado de una máquina y el hierro del estator?", opciones: ["Contacto a masa o derivación", "Cortocircuito entre espiras", "Interrupción de bobinado", "Conexión errónea"], correctaTexto: "Contacto a masa o derivación", explicacion: "Se denominan contactos a masa o derivaciones a la unión eléctrica entre el devanado de una máquina y el hierro del estator." },
  { id: 801002, tema: "U10: Mantenimiento y reparación de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué método permite detectar una conexión errónea de polaridad usando una bola metálica en el estator?", opciones: ["Impulsar la bola por el campo magnético giratorio y comprobar si gira", "Medir la resistencia con un óhmetro", "Aplicar tensión nominal directamente sin pruebas previas", "Usar un termómetro de contacto"], correctaTexto: "Impulsar la bola por el campo magnético giratorio y comprobar si gira", explicacion: "Con los devanados en estrella y tensión reducida, se impulsa una bola metálica y si no gira se puede asegurar que las conexiones son erróneas." },
  { id: 801003, tema: "U10: Mantenimiento y reparación de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué paso previo se debe dar antes de aflojar la tornillería al desmontar una máquina para rebobinado?", opciones: ["Marcar la carcasa y los escudos para volver a colocarlos en la misma posición", "Cortocircuitar el bobinado", "Retirar directamente el rotor sin anotaciones", "Aplicar barniz nuevo"], correctaTexto: "Marcar la carcasa y los escudos para volver a colocarlos en la misma posición", explicacion: "Antes de aflojar la tornillería se deberá marcar la carcasa y los escudos para que se vuelvan a colocar en la misma posición." },
  { id: 801004, tema: "U10: Mantenimiento y reparación de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué instrumento se utiliza habitualmente para detectar un cortocircuito entre espiras en el bobinado del estator?", opciones: ["El detector de cortocircuitos (growler) o la medición comparativa de impedancia por fase", "El calibre de precisión", "El tacómetro exclusivamente", "El barómetro"], correctaTexto: "El detector de cortocircuitos (growler) o la medición comparativa de impedancia por fase", explicacion: "El detector de cortocircuitos (growler) o la comparación de la impedancia medida en cada una de las tres fases permiten detectar un cortocircuito entre espiras en el bobinado del estator." },
  { id: 801005, tema: "U10: Mantenimiento y reparación de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué operación se realiza para extraer el bobinado deteriorado de un motor antes de proceder a su rebobinado?", opciones: ["El quemado o disolución del barniz seguido de la extracción de las bobinas de las ranuras", "La sustitución directa del núcleo completo sin retirar ningún bobinado", "El torneado del núcleo del estator", "La sustitución exclusiva de los rodamientos"], correctaTexto: "El quemado o disolución del barniz seguido de la extracción de las bobinas de las ranuras", explicacion: "Para extraer el bobinado deteriorado se procede al quemado controlado o disolución química del barniz de impregnación, facilitando posteriormente la extracción de las bobinas de las ranuras del núcleo." },
  { id: 801006, tema: "U10: Mantenimiento y reparación de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué dato es imprescindible registrar antes de desmontar el bobinado original de un motor que se va a rebobinar?", opciones: ["El número de espiras, sección del hilo, tipo de conexión y paso de bobina del devanado original", "Únicamente el color de la carcasa exterior del motor", "Solo el peso total del motor", "El precio de compra original del motor"], correctaTexto: "El número de espiras, sección del hilo, tipo de conexión y paso de bobina del devanado original", explicacion: "Antes de desmontar el bobinado original es imprescindible registrar todos sus datos característicos (número de espiras, sección del hilo, tipo de conexión, paso de bobina) para poder reproducirlo fielmente en el rebobinado." },
  { id: 801007, tema: "U10: Mantenimiento y reparación de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué se debe comprobar tras la introducción de las nuevas bobinas en las ranuras del estator durante un rebobinado?", opciones: ["El aislamiento de las bobinas respecto al núcleo y la correcta conexión según el esquema original", "Únicamente el color del nuevo hilo de cobre utilizado", "Solo el peso del nuevo bobinado", "Nada, se puede proceder directamente a la puesta en marcha sin comprobación"], correctaTexto: "El aislamiento de las bobinas respecto al núcleo y la correcta conexión según el esquema original", explicacion: "Tras introducir las nuevas bobinas en las ranuras, debe comprobarse su correcto aislamiento respecto al núcleo del estator y verificar que la conexión se realiza conforme al esquema original registrado antes del desmontaje." },
  { id: 801008, tema: "U10: Mantenimiento y reparación de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué avería puede provocar que un motor trifásico gire en sentido contrario al esperado tras una reparación?", opciones: ["Una inversión en el orden de conexión de dos de las tres fases de alimentación", "Un cortocircuito entre espiras del bobinado", "Un desgaste excesivo de los rodamientos", "Una resistencia de aislamiento demasiado elevada"], correctaTexto: "Una inversión en el orden de conexión de dos de las tres fases de alimentación", explicacion: "Si tras una reparación un motor trifásico gira en sentido contrario al esperado, la causa más habitual es una inversión en el orden de conexión de dos de las tres fases de alimentación." },
  { id: 801009, tema: "U10: Mantenimiento y reparación de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué se debe verificar al detectar un ruido anómalo en el rotor de jaula de ardilla de un motor asíncrono?", opciones: ["El estado de las barras del rotor (posible rotura) y el estado de los rodamientos", "Únicamente el color de la pintura exterior del motor", "Solo la tensión de alimentación sin ninguna otra comprobación", "El peso del rotor exclusivamente"], correctaTexto: "El estado de las barras del rotor (posible rotura) y el estado de los rodamientos", explicacion: "Un ruido anómalo en un motor de jaula de ardilla puede deberse a la rotura de alguna barra del rotor o a un deterioro de los rodamientos, por lo que ambos elementos deben revisarse detenidamente." },
  { id: 801010, tema: "U10: Mantenimiento y reparación de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué prueba permite detectar barras rotas en un rotor de jaula de ardilla?", opciones: ["El análisis de la corriente del motor en funcionamiento (MCSA) o la inspección visual tras el desmontaje", "La medición exclusiva de la resistencia de aislamiento del estator", "El ensayo de rigidez dieléctrica del aceite", "La medición de la velocidad de sincronismo teórica"], correctaTexto: "El análisis de la corriente del motor en funcionamiento (MCSA) o la inspección visual tras el desmontaje", explicacion: "El análisis de la firma de corriente del motor (MCSA, Motor Current Signature Analysis) en funcionamiento, o la inspección visual directa tras el desmontaje, permiten detectar barras rotas en un rotor de jaula de ardilla." },
  { id: 801011, tema: "U10: Mantenimiento y reparación de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué se debe comprobar sobre los anillos rozantes de un motor de rotor bobinado durante su mantenimiento periódico?", opciones: ["Su desgaste, ausencia de rayaduras profundas y correcto contacto de las escobillas", "Únicamente el color de los anillos sin ninguna otra comprobación", "Solo la temperatura ambiente del taller", "El peso total del rotor bobinado"], correctaTexto: "Su desgaste, ausencia de rayaduras profundas y correcto contacto de las escobillas", explicacion: "El mantenimiento de los anillos rozantes debe verificar su grado de desgaste, la ausencia de rayaduras profundas en su superficie y el correcto contacto de las escobillas correspondientes." },
  { id: 801012, tema: "U10: Mantenimiento y reparación de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué es el 'test de resistencia de aislamiento por fases' realizado tras una reparación de un motor trifásico?", opciones: ["La medición de la resistencia de aislamiento de cada fase respecto a masa y entre fases, comparando los resultados", "La medición exclusiva de la resistencia óhmica de una única fase", "Un ensayo que solo se aplica a motores monofásicos", "Un ensayo que mide únicamente la velocidad de giro"], correctaTexto: "La medición de la resistencia de aislamiento de cada fase respecto a masa y entre fases, comparando los resultados", explicacion: "El test de resistencia de aislamiento por fases consiste en medir la resistencia de aislamiento de cada una de las tres fases respecto a masa y entre sí, comparando los resultados obtenidos para detectar posibles anomalías." },
  { id: 801013, tema: "U10: Mantenimiento y reparación de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué causa habitual provoca el sobrecalentamiento generalizado de un motor trifásico en servicio?", opciones: ["Una sobrecarga mecánica, un desequilibrio de fases o una ventilación deficiente", "Un exceso de lubricación en los rodamientos", "Una tensión de alimentación exactamente igual a la nominal", "Un exceso de resistencia de aislamiento del bobinado"], correctaTexto: "Una sobrecarga mecánica, un desequilibrio de fases o una ventilación deficiente", explicacion: "El sobrecalentamiento generalizado de un motor trifásico suele deberse a una sobrecarga mecánica excesiva, un desequilibrio en las tensiones o corrientes de las tres fases, o una ventilación deficiente del propio motor." },
  { id: 801014, tema: "U10: Mantenimiento y reparación de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué precaución se debe adoptar respecto al equilibrado del nuevo rotor tras un rebobinado o reparación mecánica?", opciones: ["Realizar un equilibrado dinámico del rotor antes de su puesta en servicio definitiva", "No es necesario ningún tipo de equilibrado tras la reparación", "Aumentar deliberadamente el desequilibrio para compensar otros efectos", "Sustituir directamente los rodamientos sin verificar el equilibrado"], correctaTexto: "Realizar un equilibrado dinámico del rotor antes de su puesta en servicio definitiva", explicacion: "Tras un rebobinado o cualquier reparación mecánica que afecte al rotor, debe realizarse un equilibrado dinámico antes de la puesta en servicio definitiva, evitando vibraciones excesivas y desgaste prematuro." },
  { id: 801015, tema: "U10: Mantenimiento y reparación de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué elemento de protección eléctrica se debe verificar que esté correctamente calibrado tras la reparación de un motor trifásico?", opciones: ["El relé térmico de protección contra sobrecargas", "El colector de delgas exclusivamente", "El detector de fugas de agua", "El sensor de luminosidad ambiental"], correctaTexto: "El relé térmico de protección contra sobrecargas", explicacion: "Tras la reparación de un motor trifásico debe verificarse que el relé térmico de protección contra sobrecargas está correctamente calibrado a la intensidad nominal del motor reparado." },
  { id: 801016, tema: "U10: Mantenimiento y reparación de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué diferencia existe entre una avería eléctrica y una avería mecánica en un motor de corriente alterna?", opciones: ["La eléctrica afecta al bobinado o circuito eléctrico; la mecánica afecta a rodamientos, eje u otros elementos mecánicos", "Ambos tipos de avería son exactamente equivalentes en su diagnóstico y reparación", "La avería mecánica siempre se detecta mediante megóhmetro", "La avería eléctrica nunca provoca ruido ni vibración"], correctaTexto: "La eléctrica afecta al bobinado o circuito eléctrico; la mecánica afecta a rodamientos, eje u otros elementos mecánicos", explicacion: "Una avería eléctrica afecta al bobinado, aislamiento o circuito eléctrico de la máquina, mientras que una avería mecánica afecta a elementos como rodamientos, eje, acoplamientos u otros componentes mecánicos." },
  { id: 801017, tema: "U10: Mantenimiento y reparación de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué se debe verificar en la puesta en marcha final tras completar la reparación de un motor trifásico?", opciones: ["El sentido de giro, la ausencia de vibraciones anómalas, el consumo de corriente y la temperatura de funcionamiento", "Únicamente el aspecto estético exterior de la carcasa", "Solo el color del bobinado nuevo instalado", "Nada, se puede considerar terminada la reparación sin ninguna prueba final"], correctaTexto: "El sentido de giro, la ausencia de vibraciones anómalas, el consumo de corriente y la temperatura de funcionamiento", explicacion: "En la puesta en marcha final tras una reparación deben verificarse el sentido de giro correcto, la ausencia de vibraciones anómalas, el consumo de corriente dentro de los valores nominales y la temperatura de funcionamiento del motor." },
  { id: 801018, tema: "U10: Mantenimiento y reparación de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué documento se debe generar tras finalizar la reparación de una máquina de corriente alterna en un taller especializado?", opciones: ["Un informe o parte de reparación con las operaciones realizadas y los resultados de los ensayos finales", "No es necesario generar ningún documento tras la reparación", "Solo la factura comercial sin ningún detalle técnico", "Únicamente una fotografía de la máquina reparada"], correctaTexto: "Un informe o parte de reparación con las operaciones realizadas y los resultados de los ensayos finales", explicacion: "Tras finalizar la reparación debe generarse un informe o parte de reparación que documente las operaciones realizadas y los resultados obtenidos en los ensayos finales, sirviendo como referencia para el mantenimiento futuro." },
  { id: 801019, tema: "U10: Mantenimiento y reparación de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué medida preventiva reduce el riesgo de que la humedad ambiental afecte al aislamiento de un motor almacenado durante un largo periodo sin uso?", opciones: ["Almacenarlo en un lugar seco y aplicar calefacción anticondensación o resistencias de caldeo periódicas", "Almacenarlo directamente a la intemperie sin ninguna protección", "Sumergirlo en agua para evitar la oxidación externa", "No adoptar ninguna medida especial durante el almacenamiento prolongado"], correctaTexto: "Almacenarlo en un lugar seco y aplicar calefacción anticondensación o resistencias de caldeo periódicas", explicacion: "Para evitar que la humedad ambiental deteriore el aislamiento de un motor almacenado durante un periodo prolongado, se recomienda mantenerlo en un lugar seco y, si es posible, aplicar calefacción anticondensación o activar periódicamente resistencias de caldeo." },
  { id: 801020, tema: "U10: Mantenimiento y reparación de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué se recomienda comprobar periódicamente en el sistema de ventilación (ventilador acoplado al eje) de un motor de corriente alterna?", opciones: ["La ausencia de obstrucciones en las rejillas y el buen estado de las aspas del ventilador", "Únicamente el color de las aspas del ventilador", "El peso total del ventilador acoplado", "La velocidad de sincronismo teórica del motor"], correctaTexto: "La ausencia de obstrucciones en las rejillas y el buen estado de las aspas del ventilador", explicacion: "El mantenimiento del sistema de ventilación debe comprobar periódicamente que las rejillas no presentan obstrucciones y que las aspas del ventilador acoplado al eje se encuentran en buen estado, garantizando una correcta refrigeración del motor." }
];

const TEMA_MAQUINAS_U11_DATA = [
  { id: 801101, tema: "U11: Ensayos de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué transforma un alternador en su eje para suministrar corriente alterna por sus bornes?", opciones: ["Energía mecánica en energía eléctrica", "Energía eléctrica en energía mecánica", "Energía térmica en energía eléctrica", "Energía química en energía mecánica"], correctaTexto: "Energía mecánica en energía eléctrica", explicacion: "El alternador transforma la energía mecánica que recibe por su eje en corriente alterna suministrada por sus bornes." },
  { id: 801102, tema: "U11: Ensayos de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Cómo se llama la dinamo acoplada al eje del alternador que se utiliza como fuente de corriente continua para alimentar el bobinado inductor?", opciones: ["La excitatriz", "El colector de anillos", "El rotor de jaula", "El regulador de tensión"], correctaTexto: "La excitatriz", explicacion: "La excitatriz es la dinamo utilizada como fuente de c.c. que se acopla en el eje del alternador para alimentar el bobinado inductor." },
  { id: 801103, tema: "U11: Ensayos de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué parámetros se obtienen mediante el ensayo de cortocircuito de un generador síncrono?", opciones: ["Intensidad de cortocircuito, impedancia y reactancia síncrona", "Únicamente la velocidad de sincronismo", "Solo el factor de potencia nominal", "El rendimiento total exclusivamente"], correctaTexto: "Intensidad de cortocircuito, impedancia y reactancia síncrona", explicacion: "El ensayo de cortocircuito del generador síncrono se aplica para conocer parámetros como la intensidad de cortocircuito, la impedancia síncrona o la reactancia síncrona." },
  { id: 801104, tema: "U11: Ensayos de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué ensayo permite obtener la característica en vacío de un alternador (relación entre f.e.m. generada y corriente de excitación)?", opciones: ["El ensayo en vacío a velocidad de sincronismo constante, variando la corriente de excitación", "El ensayo de cortocircuito exclusivamente", "El ensayo de resistencia de aislamiento exclusivamente", "El ensayo de par-velocidad exclusivamente"], correctaTexto: "El ensayo en vacío a velocidad de sincronismo constante, variando la corriente de excitación", explicacion: "El ensayo en vacío del alternador se realiza a velocidad de sincronismo constante, variando progresivamente la corriente de excitación y midiendo la f.e.m. generada en bornes, sin conectar carga alguna." },
  { id: 801105, tema: "U11: Ensayos de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué es el 'triángulo de Potier' utilizado en el análisis de alternadores síncronos?", opciones: ["Una construcción gráfica que permite separar la reactancia de dispersión de los efectos de la reacción de inducido", "Un tipo de conexión trifásica exclusiva de los transformadores", "Un instrumento físico de medida de la velocidad de giro", "Un componente mecánico del sistema de excitación"], correctaTexto: "Una construcción gráfica que permite separar la reactancia de dispersión de los efectos de la reacción de inducido", explicacion: "El triángulo de Potier es una construcción gráfica, obtenida a partir de los ensayos en vacío y de cortocircuito, que permite separar el efecto de la reactancia de dispersión de la reacción de inducido en el análisis del alternador." },
  { id: 801106, tema: "U11: Ensayos de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué es la sincronización de un alternador con la red eléctrica?", opciones: ["El proceso de ajustar tensión, frecuencia, secuencia de fases y ángulo de fase del alternador antes de conectarlo a la red", "El proceso de desconectar el alternador de cualquier fuente de excitación", "Un ensayo exclusivo para motores asíncronos, no aplicable a alternadores", "Un proceso que se realiza únicamente tras una avería grave del alternador"], correctaTexto: "El proceso de ajustar tensión, frecuencia, secuencia de fases y ángulo de fase del alternador antes de conectarlo a la red", explicacion: "La sincronización es el proceso mediante el cual se ajustan la tensión, frecuencia, secuencia de fases y ángulo de fase del alternador para que coincidan con los de la red eléctrica antes de proceder a su conexión definitiva." },
  { id: 801107, tema: "U11: Ensayos de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué instrumento se utiliza tradicionalmente para verificar visualmente que dos sistemas trifásicos están en fase antes de sincronizar un alternador?", opciones: ["El sincronoscopio", "El megóhmetro", "El tacómetro exclusivamente", "El calibre de precisión"], correctaTexto: "El sincronoscopio", explicacion: "El sincronoscopio es el instrumento tradicional utilizado para verificar visualmente, mediante la posición de una aguja giratoria, que dos sistemas trifásicos están en fase antes de proceder a la sincronización del alternador con la red." },
  { id: 801108, tema: "U11: Ensayos de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué es la 'reactancia síncrona' de un alternador?", opciones: ["La reactancia equivalente que combina la reactancia de dispersión y el efecto de la reacción de inducido", "La resistencia óhmica pura del bobinado del inducido", "Un parámetro exclusivo de los motores asíncronos", "La resistencia de aislamiento medida con megóhmetro"], correctaTexto: "La reactancia equivalente que combina la reactancia de dispersión y el efecto de la reacción de inducido", explicacion: "La reactancia síncrona es una reactancia equivalente que combina el efecto de la reactancia de dispersión del devanado y el efecto magnético de la reacción de inducido, siendo fundamental en el modelo eléctrico del alternador." },
  { id: 801109, tema: "U11: Ensayos de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué relación existe entre la velocidad de giro y la frecuencia generada por un alternador síncrono de p pares de polos?", opciones: ["f = n·p/60, donde n es la velocidad en revoluciones por minuto", "La frecuencia generada es siempre independiente de la velocidad de giro", "f = n/p exclusivamente sin ninguna constante adicional", "La velocidad de giro no tiene ninguna relación con la frecuencia generada"], correctaTexto: "f = n·p/60, donde n es la velocidad en revoluciones por minuto", explicacion: "La frecuencia generada por un alternador síncrono se relaciona con su velocidad de giro y el número de pares de polos mediante la fórmula f = n·p/60, siendo n la velocidad en revoluciones por minuto y p el número de pares de polos." },
  { id: 801110, tema: "U11: Ensayos de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué ensayo permite determinar la velocidad de sincronismo y el deslizamiento de un motor asíncrono trifásico bajo distintas condiciones de carga?", opciones: ["El ensayo de par-velocidad (o de carga variable) con medición de la velocidad real del rotor", "El ensayo exclusivo de resistencia de aislamiento", "El ensayo de rigidez dieléctrica del aceite", "El ensayo exclusivo de calentamiento térmico sin medición mecánica"], correctaTexto: "El ensayo de par-velocidad (o de carga variable) con medición de la velocidad real del rotor", explicacion: "El ensayo de par-velocidad, aplicando distintas condiciones de carga y midiendo la velocidad real de giro del rotor mediante tacómetro, permite determinar el deslizamiento del motor asíncrono trifásico en cada punto de funcionamiento." },
  { id: 801111, tema: "U11: Ensayos de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué es el 'ensayo de rotor bloqueado' en un motor asíncrono trifásico y qué parámetros permite obtener?", opciones: ["Un ensayo con el rotor inmovilizado que permite obtener la impedancia de cortocircuito y las pérdidas en el cobre a intensidad nominal", "Un ensayo que solo puede realizarse con el motor girando a plena velocidad", "Un ensayo exclusivo de los transformadores, no aplicable a motores", "Un ensayo que mide únicamente la resistencia de aislamiento"], correctaTexto: "Un ensayo con el rotor inmovilizado que permite obtener la impedancia de cortocircuito y las pérdidas en el cobre a intensidad nominal", explicacion: "El ensayo de rotor bloqueado, análogo al ensayo de cortocircuito de un transformador, se realiza con el rotor inmovilizado mecánicamente y permite obtener la impedancia de cortocircuito del motor y las pérdidas en el cobre a intensidad nominal." },
  { id: 801112, tema: "U11: Ensayos de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué parámetros se obtienen mediante el ensayo en vacío de un motor asíncrono trifásico girando libremente sin carga?", opciones: ["Las pérdidas en el hierro, las pérdidas mecánicas y la corriente de magnetización", "Únicamente la resistencia de aislamiento del bobinado", "Solo la velocidad de sincronismo teórica sin ninguna medición real", "El peso total del motor exclusivamente"], correctaTexto: "Las pérdidas en el hierro, las pérdidas mecánicas y la corriente de magnetización", explicacion: "El ensayo en vacío de un motor asíncrono trifásico, girando libremente sin carga mecánica aplicada, permite obtener las pérdidas en el hierro, las pérdidas mecánicas (rozamiento y ventilación) y la corriente de magnetización del motor." },
  { id: 801113, tema: "U11: Ensayos de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué es el circuito equivalente de un motor asíncrono trifásico y para qué se utiliza?", opciones: ["Un modelo eléctrico simplificado que representa el comportamiento del motor mediante resistencias y reactancias equivalentes, útil para calcular su comportamiento bajo distintas condiciones", "Un esquema exclusivo para representar la disposición física de la carcasa del motor", "Un documento que sustituye completamente a la placa de características", "Un tipo de ensayo mecánico sin ninguna representación eléctrica"], correctaTexto: "Un modelo eléctrico simplificado que representa el comportamiento del motor mediante resistencias y reactancias equivalentes, útil para calcular su comportamiento bajo distintas condiciones", explicacion: "El circuito equivalente es un modelo eléctrico simplificado (similar al de un transformador) que representa el comportamiento del motor asíncrono mediante resistencias y reactancias equivalentes, permitiendo calcular su comportamiento (corriente, par, rendimiento) bajo distintas condiciones de funcionamiento." },
  { id: 801114, tema: "U11: Ensayos de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué relación existe entre el par de arranque y la resistencia del rotor en un motor asíncrono de rotor bobinado?", opciones: ["Al aumentar la resistencia rotórica externa conectada, aumenta el par de arranque hasta un valor óptimo, reduciendo además la corriente de arranque", "La resistencia del rotor no tiene ninguna influencia sobre el par de arranque del motor", "A mayor resistencia rotórica, siempre menor par de arranque en cualquier caso", "El par de arranque depende exclusivamente de la tensión de alimentación, nunca de la resistencia rotórica"], correctaTexto: "Al aumentar la resistencia rotórica externa conectada, aumenta el par de arranque hasta un valor óptimo, reduciendo además la corriente de arranque", explicacion: "En un motor de rotor bobinado, conectar resistencias externas al circuito rotórico permite aumentar el par de arranque hasta un valor óptimo y, simultáneamente, reducir la corriente de arranque, siendo esta la base del método de arranque por resistencias rotóricas." },
  { id: 801115, tema: "U11: Ensayos de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué se entiende por 'curva par-deslizamiento' de un motor asíncrono trifásico?", opciones: ["La representación gráfica del par motor desarrollado en función del deslizamiento del rotor", "La representación gráfica de la resistencia de aislamiento frente al tiempo de funcionamiento", "La representación gráfica exclusiva de la temperatura del bobinado frente al tiempo", "La representación gráfica del peso de la máquina frente a su potencia nominal"], correctaTexto: "La representación gráfica del par motor desarrollado en función del deslizamiento del rotor", explicacion: "La curva par-deslizamiento representa gráficamente cómo varía el par motor desarrollado por el motor asíncrono en función del deslizamiento del rotor, siendo fundamental para entender su comportamiento en arranque y en régimen nominal." },
  { id: 801116, tema: "U11: Ensayos de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué es el 'par máximo' (o par de vuelco) de un motor asíncrono trifásico?", opciones: ["El valor máximo de par que puede desarrollar el motor antes de que un aumento de la carga provoque su detención (vuelco)", "El par nominal de funcionamiento continuo del motor", "El par de arranque en el instante de conexión a la red", "El par mínimo registrado durante todo el ciclo de funcionamiento"], correctaTexto: "El valor máximo de par que puede desarrollar el motor antes de que un aumento de la carga provoque su detención (vuelco)", explicacion: "El par máximo o par de vuelco es el valor más elevado de par que el motor asíncrono es capaz de desarrollar; si la carga mecánica exigida supera este valor, el motor se detiene bruscamente (vuelco)." },
  { id: 801117, tema: "U11: Ensayos de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué normativa establece las clases de rendimiento energético (IE1, IE2, IE3, IE4) para motores eléctricos trifásicos?", opciones: ["La norma internacional IEC 60034-30", "El Reglamento Electrotécnico de Baja Tensión exclusivamente", "El Código Técnico de la Edificación exclusivamente", "La Ley 31/1995 de Prevención de Riesgos Laborales"], correctaTexto: "La norma internacional IEC 60034-30", explicacion: "La norma internacional IEC 60034-30 establece las clases de eficiencia energética (IE1 Estándar, IE2 Alta, IE3 Premium, IE4 Súper Premium) aplicables a los motores eléctricos trifásicos." },
  { id: 801118, tema: "U11: Ensayos de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué finalidad tiene medir el factor de potencia de un motor asíncrono trifásico durante los ensayos de caracterización?", opciones: ["Determinar el desfase entre tensión y corriente, relevante para el dimensionado de la instalación y la facturación eléctrica", "Determinar exclusivamente la velocidad de giro del rotor", "Medir la resistencia de aislamiento del bobinado", "Calcular el peso total del motor ensayado"], correctaTexto: "Determinar el desfase entre tensión y corriente, relevante para el dimensionado de la instalación y la facturación eléctrica", explicacion: "El factor de potencia indica el desfase entre la tensión y la corriente absorbida por el motor, siendo un parámetro relevante tanto para el correcto dimensionado de la instalación eléctrica como para evitar penalizaciones en la facturación por energía reactiva." },
  { id: 801119, tema: "U11: Ensayos de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué precaución de seguridad es especialmente relevante al realizar el ensayo de rotor bloqueado en un motor de gran potencia?", opciones: ["Limitar el tiempo de duración del ensayo para evitar un sobrecalentamiento excesivo del bobinado", "No existe ninguna precaución especial, se puede mantener el ensayo indefinidamente", "Aumentar la tensión de alimentación al máximo posible sin ningún límite de tiempo", "Desconectar completamente el sistema de ventilación durante el ensayo"], correctaTexto: "Limitar el tiempo de duración del ensayo para evitar un sobrecalentamiento excesivo del bobinado", explicacion: "Dado que en el ensayo de rotor bloqueado circula una corriente elevada sin que exista ventilación por giro del rotor, es fundamental limitar el tiempo de duración del ensayo para evitar un sobrecalentamiento excesivo y dañino del bobinado." },
  { id: 801120, tema: "U11: Ensayos de máquinas eléctricas de corriente alterna (TEST OFICIAL)", texto: "¿Qué información adicional aporta un analizador de redes durante el ensayo de un motor de corriente alterna, más allá de la simple medida de tensión e intensidad?", opciones: ["Permite analizar armónicos, factor de potencia, potencia activa/reactiva/aparente y desequilibrios entre fases", "Únicamente mide la temperatura ambiente del taller", "Solo indica el color recomendado para el cableado de conexión", "Exclusivamente mide la velocidad de giro mecánica del motor"], correctaTexto: "Permite analizar armónicos, factor de potencia, potencia activa/reactiva/aparente y desequilibrios entre fases", explicacion: "Un analizador de redes proporciona información avanzada durante el ensayo, incluyendo el análisis de armónicos, factor de potencia, potencias activa, reactiva y aparente, así como posibles desequilibrios entre las tres fases de alimentación del motor." }
];

const TEMA_MAQUINAS_U12_DATA = [
  { id: 801201, tema: "U12: Instalación de los motores eléctricos (TEST OFICIAL)", texto: "¿Qué separación mínima del suelo deben tener las máquinas con sistemas de ventilación externa para que pueda pasar el aire?", opciones: ["50 mm", "5 mm", "500 mm", "10 mm"], correctaTexto: "50 mm", explicacion: "Las máquinas que incorporen sistemas de ventilación externa deberán estar separadas del suelo un mínimo de 50 mm para que pueda pasar el aire." },
  { id: 801202, tema: "U12: Instalación de los motores eléctricos (TEST OFICIAL)", texto: "¿Qué tipo de base se utiliza en motores con transmisión por poleas para poder tensar las correas?", opciones: ["Bases deslizantes", "Bases de hormigón fijas", "Bases especiales antivibración", "Bases metálicas rígidas"], correctaTexto: "Bases deslizantes", explicacion: "Los motores que realicen transmisión por poleas se montarán sobre bases deslizantes con el objetivo de poder tensar las correas." },
  { id: 801203, tema: "U12: Instalación de los motores eléctricos (TEST OFICIAL)", texto: "¿Cuál es la mejor opción de acoplamiento entre motor y máquina accionada por su ahorro de costes y ausencia de deslizamientos?", opciones: ["El acoplamiento directo", "El acoplamiento por correas", "El acoplamiento por engranajes", "El acoplamiento hidráulico"], correctaTexto: "El acoplamiento directo", explicacion: "El acoplamiento directo es siempre la mejor opción por el ahorro de costes, reducción de tamaños, ausencia de deslizamientos y mayor seguridad." },
  { id: 801204, tema: "U12: Instalación de los motores eléctricos (TEST OFICIAL)", texto: "¿Qué elemento mecánico se utiliza para conectar el eje del motor con el eje de la máquina accionada en un acoplamiento directo?", opciones: ["El acoplamiento elástico o rígido", "La correa trapezoidal", "El engranaje reductor", "La polea acanalada"], correctaTexto: "El acoplamiento elástico o rígido", explicacion: "En un acoplamiento directo se emplea un acoplamiento mecánico (elástico o rígido) que une físicamente el eje del motor con el eje de la máquina accionada, transmitiendo el giro sin deslizamiento." },
  { id: 801205, tema: "U12: Instalación de los motores eléctricos (TEST OFICIAL)", texto: "¿Qué precaución se debe tener al alinear el motor y la máquina accionada en un acoplamiento directo?", opciones: ["Verificar la correcta alineación de los ejes para evitar vibraciones y desgaste prematuro de los rodamientos", "No es necesario alinear los ejes en ningún caso", "Desalinear ligeramente los ejes de forma deliberada", "Alinear únicamente el eje del motor, sin considerar el de la máquina accionada"], correctaTexto: "Verificar la correcta alineación de los ejes para evitar vibraciones y desgaste prematuro de los rodamientos", explicacion: "Una correcta alineación de los ejes en el acoplamiento directo es fundamental para evitar vibraciones excesivas y el desgaste prematuro de los rodamientos tanto del motor como de la máquina accionada." },
  { id: 801206, tema: "U12: Instalación de los motores eléctricos (TEST OFICIAL)", texto: "¿Qué ventaja ofrece la transmisión por correas trapezoidales frente al acoplamiento directo?", opciones: ["Permite variar la relación de transmisión mediante distintos diámetros de polea y absorbe cierto grado de desalineación", "Siempre resulta más económica y eficiente que el acoplamiento directo en cualquier caso", "Elimina por completo la necesidad de mantenimiento", "No requiere ningún tipo de tensado periódico de la correa"], correctaTexto: "Permite variar la relación de transmisión mediante distintos diámetros de polea y absorbe cierto grado de desalineación", explicacion: "La transmisión por correas trapezoidales permite variar la relación de velocidades utilizando poleas de distinto diámetro y tolera cierto grado de desalineación entre ejes, a costa de un rendimiento ligeramente inferior al acoplamiento directo." },
  { id: 801207, tema: "U12: Instalación de los motores eléctricos (TEST OFICIAL)", texto: "¿Qué se debe comprobar periódicamente en una transmisión por correas trapezoidales?", opciones: ["La tensión de la correa y su estado de desgaste, evitando tanto el destensado como el sobretensado excesivo", "Únicamente el color de la correa", "Solo la velocidad de giro del motor sin ninguna otra comprobación", "El peso total del conjunto motor-polea"], correctaTexto: "La tensión de la correa y su estado de desgaste, evitando tanto el destensado como el sobretensado excesivo", explicacion: "En una transmisión por correas debe comprobarse periódicamente la tensión adecuada de la correa y su estado de desgaste, ya que tanto un destensado como un sobretensado excesivo perjudican el rendimiento y la vida útil de la transmisión." },
  { id: 801208, tema: "U12: Instalación de los motores eléctricos (TEST OFICIAL)", texto: "¿Qué tipo de fijación se recomienda para motores de gran potencia sometidos a esfuerzos y vibraciones importantes?", opciones: ["Fijación sobre bancada de hormigón con pernos de anclaje adecuadamente dimensionados", "Fijación exclusivamente mediante adhesivo industrial", "No requiere ningún tipo de fijación especial independientemente de su potencia", "Fijación mediante simple apoyo sin ningún anclaje"], correctaTexto: "Fijación sobre bancada de hormigón con pernos de anclaje adecuadamente dimensionados", explicacion: "Los motores de gran potencia, sometidos a esfuerzos y vibraciones importantes, se instalan habitualmente sobre una bancada de hormigón fijada mediante pernos de anclaje adecuadamente dimensionados para garantizar su estabilidad." },
  { id: 801209, tema: "U12: Instalación de los motores eléctricos (TEST OFICIAL)", texto: "¿Qué condición ambiental debe evitarse en el lugar de instalación de un motor eléctrico estándar (sin protección especial)?", opciones: ["La presencia de polvo, humedad excesiva o atmósferas corrosivas que puedan dañar el motor", "La presencia de una temperatura ambiente moderada dentro de los límites normales", "La existencia de una adecuada ventilación del recinto", "La existencia de un espacio suficiente alrededor del motor para su mantenimiento"], correctaTexto: "La presencia de polvo, humedad excesiva o atmósferas corrosivas que puedan dañar el motor", explicacion: "Un motor eléctrico estándar, sin un grado de protección especial adecuado, debe instalarse evitando ambientes con polvo excesivo, humedad elevada o atmósferas corrosivas que puedan deteriorar sus componentes internos." },
  { id: 801210, tema: "U12: Instalación de los motores eléctricos (TEST OFICIAL)", texto: "¿Qué elemento de protección eléctrica debe instalarse siempre en la alimentación de un motor trifásico según el REBT?", opciones: ["Protección contra sobrecargas y contra cortocircuitos (relé térmico y magnetotérmico o fusibles)", "Únicamente un interruptor manual sin ningún elemento de protección adicional", "Solo un fusible de vidrio de baja capacidad", "Ningún elemento de protección es obligatorio para motores de baja potencia"], correctaTexto: "Protección contra sobrecargas y contra cortocircuitos (relé térmico y magnetotérmico o fusibles)", explicacion: "El REBT exige que todo motor trifásico disponga de protección contra sobrecargas (relé térmico) y contra cortocircuitos (interruptor magnetotérmico o fusibles adecuados) en su alimentación eléctrica." },
  { id: 801211, tema: "U12: Instalación de los motores eléctricos (TEST OFICIAL)", texto: "¿Qué sección mínima de cable se debe emplear en la conexión de un motor eléctrico según la normativa?", opciones: ["La calculada en función de la intensidad nominal del motor y la longitud del cableado, conforme al REBT", "Siempre la sección mínima disponible en el mercado sin ningún cálculo previo", "Una sección fija de 1,5 mm² independientemente de la potencia del motor", "No existe ninguna exigencia normativa sobre la sección del cableado"], correctaTexto: "La calculada en función de la intensidad nominal del motor y la longitud del cableado, conforme al REBT", explicacion: "La sección del cable de conexión de un motor eléctrico debe calcularse en función de su intensidad nominal, la longitud del cableado y la caída de tensión admisible, conforme a lo establecido en el REBT." },
  { id: 801212, tema: "U12: Instalación de los motores eléctricos (TEST OFICIAL)", texto: "¿Qué método de arranque se recomienda para motores trifásicos de potencia elevada con el fin de reducir la corriente de arranque en la red?", opciones: ["El arranque estrella-triángulo o mediante variador de frecuencia (arranque suave)", "El arranque directo a plena tensión en todos los casos sin ninguna excepción", "No adoptar ninguna medida especial independientemente de la potencia del motor", "El arranque manual mediante reóstato de campo en motores trifásicos"], correctaTexto: "El arranque estrella-triángulo o mediante variador de frecuencia (arranque suave)", explicacion: "Para motores trifásicos de potencia elevada se recomiendan métodos de arranque que reduzcan la corriente de arranque en la red, como el arranque estrella-triángulo o el uso de un variador de frecuencia (arranque suave)." },
  { id: 801213, tema: "U12: Instalación de los motores eléctricos (TEST OFICIAL)", texto: "¿Qué es un variador de frecuencia y qué ventaja aporta en la instalación de un motor eléctrico?", opciones: ["Un dispositivo electrónico que permite regular la velocidad del motor variando la frecuencia de alimentación, reduciendo también la corriente de arranque", "Un dispositivo que solo permite arrancar el motor a velocidad fija, sin ninguna regulación", "Un elemento exclusivamente mecánico sin ninguna función eléctrica", "Un dispositivo que aumenta indefinidamente la tensión de alimentación del motor"], correctaTexto: "Un dispositivo electrónico que permite regular la velocidad del motor variando la frecuencia de alimentación, reduciendo también la corriente de arranque", explicacion: "El variador de frecuencia es un dispositivo electrónico que regula la velocidad de un motor de corriente alterna variando la frecuencia (y tensión) de alimentación, permitiendo además un arranque suave con menor corriente de pico." },
  { id: 801214, tema: "U12: Instalación de los motores eléctricos (TEST OFICIAL)", texto: "¿Qué espacio libre mínimo debe respetarse alrededor de un motor eléctrico instalado, según las recomendaciones habituales de mantenimiento?", opciones: ["El espacio suficiente para permitir las operaciones de mantenimiento, inspección visual y correcta ventilación", "No es necesario dejar ningún espacio libre alrededor del motor", "Únicamente el espacio necesario para el paso del cableado de alimentación", "Un espacio fijo de exactamente 1 metro en todos los casos sin excepción"], correctaTexto: "El espacio suficiente para permitir las operaciones de mantenimiento, inspección visual y correcta ventilación", explicacion: "Alrededor de un motor eléctrico instalado debe respetarse un espacio libre suficiente que permita realizar las operaciones habituales de mantenimiento, la inspección visual periódica y garantizar una correcta ventilación del equipo." },
  { id: 801215, tema: "U12: Instalación de los motores eléctricos (TEST OFICIAL)", texto: "¿Qué se debe comprobar respecto a la puesta a tierra al instalar un motor eléctrico?", opciones: ["Que la carcasa del motor quede correctamente conectada al circuito de puesta a tierra de la instalación", "Que la carcasa del motor permanezca completamente aislada de cualquier conexión a tierra", "Que solo el neutro de la instalación se conecte a tierra, nunca la carcasa del motor", "Que la puesta a tierra sea opcional en motores de baja potencia"], correctaTexto: "Que la carcasa del motor quede correctamente conectada al circuito de puesta a tierra de la instalación", explicacion: "Es imprescindible verificar que la carcasa metálica del motor queda correctamente conectada al circuito de puesta a tierra de la instalación, protegiendo a las personas frente a contactos eléctricos indirectos." },
  { id: 801216, tema: "U12: Instalación de los motores eléctricos (TEST OFICIAL)", texto: "¿Qué grado de protección IP resulta adecuado para un motor instalado a la intemperie o en ambientes con proyección de agua?", opciones: ["Un grado de protección elevado, como IP55 o superior", "Un grado de protección mínimo, como IP00", "El grado de protección es irrelevante en instalaciones a la intemperie", "Únicamente se requiere protección frente a polvo, no frente a agua"], correctaTexto: "Un grado de protección elevado, como IP55 o superior", explicacion: "Un motor instalado a la intemperie o en ambientes con proyección de agua debe disponer de un grado de protección elevado (por ejemplo, IP55 o superior) que garantice su estanqueidad frente a polvo y agua." },
  { id: 801217, tema: "U12: Instalación de los motores eléctricos (TEST OFICIAL)", texto: "¿Qué elemento se instala habitualmente para amortiguar las vibraciones transmitidas por un motor a la estructura del edificio?", opciones: ["Los soportes o taquetes antivibratorios (amortiguadores elásticos)", "Un cableado de mayor sección de lo necesario", "Un ventilador adicional de mayor tamaño", "Un fusible de mayor capacidad"], correctaTexto: "Los soportes o taquetes antivibratorios (amortiguadores elásticos)", explicacion: "Los soportes o taquetes antivibratorios, fabricados con materiales elásticos, se instalan bajo la bancada del motor para amortiguar y reducir la transmisión de vibraciones a la estructura del edificio." },
  { id: 801218, tema: "U12: Instalación de los motores eléctricos (TEST OFICIAL)", texto: "¿Qué documentación debe entregarse tras la instalación de un motor eléctrico industrial de cierta potencia?", opciones: ["El certificado de instalación eléctrica y la documentación técnica del motor y sus protecciones", "No es necesario entregar ningún tipo de documentación", "Únicamente la factura comercial del motor", "Solo el manual genérico del fabricante sin ningún certificado adicional"], correctaTexto: "El certificado de instalación eléctrica y la documentación técnica del motor y sus protecciones", explicacion: "Tras la instalación de un motor eléctrico industrial debe entregarse el certificado de instalación eléctrica correspondiente, junto con la documentación técnica del motor y de las protecciones eléctricas instaladas." },
  { id: 801219, tema: "U12: Instalación de los motores eléctricos (TEST OFICIAL)", texto: "¿Qué precaución se debe tener respecto a la posición de montaje de un motor eléctrico indicada por el fabricante?", opciones: ["Respetar la posición de montaje especificada (horizontal, vertical, etc.) para garantizar la correcta lubricación y refrigeración", "La posición de montaje es completamente indiferente para cualquier motor", "Siempre se debe instalar en posición vertical independientemente de las indicaciones del fabricante", "La posición de montaje solo afecta al aspecto estético de la instalación"], correctaTexto: "Respetar la posición de montaje especificada (horizontal, vertical, etc.) para garantizar la correcta lubricación y refrigeración", explicacion: "Debe respetarse la posición de montaje especificada por el fabricante (horizontal, vertical con eje hacia arriba o hacia abajo, etc.), ya que de ello depende la correcta lubricación de los rodamientos y la refrigeración adecuada del motor." },
  { id: 801220, tema: "U12: Instalación de los motores eléctricos (TEST OFICIAL)", texto: "¿Qué comprobación final se recomienda realizar tras completar la instalación de un motor eléctrico, antes de su puesta en marcha definitiva?", opciones: ["Verificar la resistencia de aislamiento, las conexiones eléctricas, la alineación mecánica y el sentido de giro previsto", "Poner en marcha el motor directamente a plena carga sin ninguna comprobación previa", "Comprobar únicamente el aspecto estético de la instalación", "No es necesaria ninguna comprobación adicional tras la instalación física"], correctaTexto: "Verificar la resistencia de aislamiento, las conexiones eléctricas, la alineación mecánica y el sentido de giro previsto", explicacion: "Antes de la puesta en marcha definitiva de un motor recién instalado deben verificarse la resistencia de aislamiento, la correcta ejecución de las conexiones eléctricas, la alineación mecánica del acoplamiento y comprobar el sentido de giro previsto." }
];

const TEMA_MAQUINAS_U13_DATA = [
  { id: 801301, tema: "U13: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué ley define el riesgo laboral como la posibilidad de que un trabajador sufra un daño derivado del trabajo?", opciones: ["Ley 31/1995 de Prevención de Riesgos Laborales", "Ley Orgánica 3/2018", "Real Decreto 1215/1997", "Ley 21/2013"], correctaTexto: "Ley 31/1995 de Prevención de Riesgos Laborales", explicacion: "La Ley 31/95 del 8 de noviembre, sobre Prevención de Riesgos Laborales, define el riesgo laboral como la posibilidad de que un trabajador sufra un determinado daño derivado del trabajo." },
  { id: 801302, tema: "U13: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué documento integra la actividad preventiva de la empresa en su sistema general de gestión?", opciones: ["El Plan de prevención de riesgos laborales", "El manual de calidad ISO", "El convenio colectivo", "El plan de marketing"], correctaTexto: "El Plan de prevención de riesgos laborales", explicacion: "El Plan de prevención de riesgos laborales es la herramienta a través de la cual se integra la actividad preventiva de la empresa en su sistema general de gestión." },
  { id: 801303, tema: "U13: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué tensión máxima en corriente alterna soportan los cascos de protección con aislamiento a baja tensión?", opciones: ["1000 V", "230 V", "500 V", "5000 V"], correctaTexto: "1000 V", explicacion: "Existen cascos que incorporan protección aislante a baja tensión de 1000 V en corriente alterna y 1500 V en corriente continua." },
  { id: 801304, tema: "U13: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué se entiende por accidente de trabajo según la normativa laboral española?", opciones: ["Toda lesión corporal que el trabajador sufra con ocasión o como consecuencia del trabajo que ejecuta por cuenta ajena", "Cualquier lesión sufrida fuera del horario laboral sin ninguna relación con el trabajo", "Solo las lesiones que requieren hospitalización prolongada", "Un incidente sin ninguna lesión física asociada"], correctaTexto: "Toda lesión corporal que el trabajador sufra con ocasión o como consecuencia del trabajo que ejecuta por cuenta ajena", explicacion: "Se considera accidente de trabajo toda lesión corporal que el trabajador sufra con ocasión o como consecuencia del trabajo que ejecuta por cuenta ajena, según establece la normativa laboral española." },
  { id: 801305, tema: "U13: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué son los Equipos de Protección Individual (EPI) y qué función cumplen en un taller de máquinas eléctricas?", opciones: ["Equipos destinados a ser llevados por el trabajador para protegerlo de riesgos que puedan amenazar su seguridad o salud", "Equipos exclusivos para la protección de las máquinas, no de las personas", "Un tipo de herramienta de medida eléctrica", "Un sistema de ventilación del taller"], correctaTexto: "Equipos destinados a ser llevados por el trabajador para protegerlo de riesgos que puedan amenazar su seguridad o salud", explicacion: "Los Equipos de Protección Individual (EPI) son equipos destinados a ser llevados por el trabajador para protegerlo de uno o varios riesgos que puedan amenazar su seguridad o su salud durante el trabajo." },
  { id: 801306, tema: "U13: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué medida preventiva debe aplicarse siempre antes de manipular una máquina eléctrica desconectada de la red?", opciones: ["Verificar la ausencia de tensión mediante un detector homologado, aunque se crea que está desconectada", "Confiar en la desconexión sin realizar ninguna comprobación adicional", "Tocar directamente los conductores para verificar la ausencia de tensión", "No es necesaria ninguna comprobación si la máquina lleva mucho tiempo parada"], correctaTexto: "Verificar la ausencia de tensión mediante un detector homologado, aunque se crea que está desconectada", explicacion: "Antes de manipular cualquier máquina eléctrica, incluso si se cree que está desconectada, debe verificarse la ausencia de tensión mediante un detector homologado, como parte de las cinco reglas de oro de la seguridad eléctrica." },
  { id: 801307, tema: "U13: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué gestor debe encargarse de la retirada de residuos peligrosos generados en un taller de máquinas eléctricas, como aceites o disolventes usados?", opciones: ["Un gestor de residuos autorizado conforme a la normativa ambiental vigente", "Cualquier empresa de transporte sin autorización específica", "El propio trabajador, vertiéndolos directamente al alcantarillado", "No es necesario gestionar estos residuos de ninguna forma especial"], correctaTexto: "Un gestor de residuos autorizado conforme a la normativa ambiental vigente", explicacion: "Los residuos peligrosos generados en un taller de máquinas eléctricas, como aceites dieléctricos o disolventes usados, deben ser retirados exclusivamente por un gestor de residuos autorizado conforme a la normativa ambiental vigente." },
  { id: 801308, tema: "U13: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué tipo de guantes se deben emplear para trabajos con riesgo eléctrico en baja tensión?", opciones: ["Guantes aislantes homologados según la clase de tensión de trabajo", "Guantes de cuero comunes sin ninguna certificación aislante", "Guantes de algodón sin ninguna propiedad aislante", "No es necesario emplear ningún tipo de guante en baja tensión"], correctaTexto: "Guantes aislantes homologados según la clase de tensión de trabajo", explicacion: "Para trabajos con riesgo eléctrico deben emplearse guantes aislantes homologados, seleccionados según la clase de tensión correspondiente a la instalación en la que se va a trabajar." },
  { id: 801309, tema: "U13: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué obligación tiene el empresario respecto a la formación en prevención de riesgos laborales de los trabajadores de un taller de máquinas eléctricas?", opciones: ["Garantizar que cada trabajador reciba una formación teórica y práctica suficiente y adecuada en materia preventiva", "No tiene ninguna obligación formativa específica al respecto", "Delegar toda la responsabilidad formativa exclusivamente en el propio trabajador", "Formar únicamente a los trabajadores de nueva incorporación, sin actualización posterior"], correctaTexto: "Garantizar que cada trabajador reciba una formación teórica y práctica suficiente y adecuada en materia preventiva", explicacion: "El empresario está obligado a garantizar que cada trabajador reciba una formación teórica y práctica, suficiente y adecuada, en materia de prevención de riesgos laborales, centrada en su puesto de trabajo específico." },
  { id: 801310, tema: "U13: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué medida de protección colectiva es recomendable en un taller de máquinas eléctricas para evitar el contacto accidental con partes móviles?", opciones: ["La instalación de resguardos o protecciones mecánicas en las partes móviles de las máquinas", "Prescindir de cualquier tipo de resguardo para facilitar el acceso a la máquina", "Confiar exclusivamente en la atención del trabajador sin ninguna protección física", "Reducir la velocidad de giro de la máquina como única medida preventiva"], correctaTexto: "La instalación de resguardos o protecciones mecánicas en las partes móviles de las máquinas", explicacion: "La instalación de resguardos o protecciones mecánicas en las partes móviles de las máquinas (poleas, correas, acoplamientos) es una medida de protección colectiva fundamental para evitar el contacto accidental de los trabajadores." },
  { id: 801311, tema: "U13: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué se debe hacer en caso de detectar un incendio de origen eléctrico en un taller de máquinas eléctricas?", opciones: ["Utilizar extintores adecuados para fuegos eléctricos (CO2 o polvo) y nunca agua mientras exista tensión", "Utilizar agua directamente sobre el equipo en tensión", "Ignorar el incendio si es de pequeña magnitud", "Intentar apagarlo soplando directamente sobre las llamas"], correctaTexto: "Utilizar extintores adecuados para fuegos eléctricos (CO2 o polvo) y nunca agua mientras exista tensión", explicacion: "Ante un incendio de origen eléctrico deben utilizarse extintores adecuados para fuegos eléctricos, como los de CO2 o polvo, evitando en todo momento el uso de agua mientras exista riesgo de tensión eléctrica presente." },
  { id: 801312, tema: "U13: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué protección auditiva se recomienda utilizar en talleres con máquinas que generan un nivel de ruido elevado?", opciones: ["Tapones auditivos o auriculares de protección homologados según el nivel de ruido", "No es necesario ningún tipo de protección auditiva en un taller de máquinas eléctricas", "Solo es necesaria la protección auditiva si el ruido supera los 150 dB", "Bastan unos auriculares de música convencionales sin ninguna certificación"], correctaTexto: "Tapones auditivos o auriculares de protección homologados según el nivel de ruido", explicacion: "En talleres con máquinas que generan niveles de ruido elevados es recomendable el uso de tapones auditivos o auriculares de protección homologados, adecuados al nivel de ruido presente en el puesto de trabajo." },
  { id: 801313, tema: "U13: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué residuo generado en el mantenimiento de transformadores debe tratarse con especial cuidado por su posible contenido en PCB?", opciones: ["El aceite dieléctrico usado", "El papel y cartón de embalaje", "Los restos de comida del personal", "El agua de limpieza sin contaminantes"], correctaTexto: "El aceite dieléctrico usado", explicacion: "El aceite dieléctrico usado en transformadores antiguos puede contener PCB (bifenilos policlorados), sustancias altamente contaminantes, por lo que debe tratarse como residuo peligroso con especial cuidado." },
  { id: 801314, tema: "U13: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué establece el principio de acción preventiva relacionado con 'combatir los riesgos en su origen'?", opciones: ["Priorizar la eliminación o reducción del riesgo desde su causa, antes que recurrir a protecciones individuales", "Priorizar siempre el uso de EPI frente a cualquier otra medida preventiva", "No adoptar ninguna medida hasta que se produzca un accidente", "Delegar exclusivamente en el trabajador la responsabilidad de evitar el riesgo"], correctaTexto: "Priorizar la eliminación o reducción del riesgo desde su causa, antes que recurrir a protecciones individuales", explicacion: "El principio de 'combatir los riesgos en su origen' establece la prioridad de eliminar o reducir el riesgo actuando sobre su causa, antes de recurrir como última opción a las protecciones individuales del trabajador." },
  { id: 801315, tema: "U13: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué es la señalización de seguridad en un taller de máquinas eléctricas y qué finalidad tiene?", opciones: ["El conjunto de señales que informan, advierten o prohíben determinadas acciones para prevenir riesgos", "Un elemento exclusivamente decorativo sin ninguna función preventiva", "Un sistema que sustituye completamente a la formación de los trabajadores", "Un requisito que solo aplica a talleres de gran tamaño"], correctaTexto: "El conjunto de señales que informan, advierten o prohíben determinadas acciones para prevenir riesgos", explicacion: "La señalización de seguridad es el conjunto de señales (informativas, de advertencia, de prohibición u obligación) que ayudan a identificar riesgos y a prevenir accidentes en el taller de máquinas eléctricas." },
  { id: 801316, tema: "U13: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué actuación se debe realizar ante un accidente eléctrico en el que la víctima permanece en contacto con un elemento en tensión?", opciones: ["Cortar la alimentación eléctrica antes de tocar a la víctima, o separarla usando material aislante si no es posible cortar la corriente", "Tocar directamente a la víctima para socorrerla sin ninguna precaución previa", "Esperar a que la víctima se suelte por sí misma sin intervenir", "Verter agua sobre la víctima para reanimarla"], correctaTexto: "Cortar la alimentación eléctrica antes de tocar a la víctima, o separarla usando material aislante si no es posible cortar la corriente", explicacion: "Ante un accidente eléctrico con contacto directo, lo primero es cortar la alimentación eléctrica; si no es posible, se debe separar a la víctima utilizando material aislante, nunca tocándola directamente sin protección." },
  { id: 801317, tema: "U13: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué documento recoge la identificación y evaluación de los riesgos existentes en cada puesto de trabajo del taller?", opciones: ["La evaluación de riesgos laborales del puesto de trabajo", "El manual de instrucciones genérico de las máquinas", "El convenio colectivo del sector", "La factura de compra de los equipos de protección"], correctaTexto: "La evaluación de riesgos laborales del puesto de trabajo", explicacion: "La evaluación de riesgos laborales es el documento que identifica y evalúa los riesgos específicos existentes en cada puesto de trabajo, sirviendo de base para planificar las medidas preventivas necesarias." },
  { id: 801318, tema: "U13: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué medida ambiental se recomienda para reducir el impacto de los residuos metálicos generados en un taller de máquinas eléctricas?", opciones: ["La separación y reciclaje de metales como cobre, aluminio y acero a través de gestores autorizados", "Verter los residuos metálicos junto con los residuos orgánicos sin separación alguna", "Quemar los residuos metálicos en el propio taller sin ningún control", "Almacenar indefinidamente los residuos sin ninguna gestión posterior"], correctaTexto: "La separación y reciclaje de metales como cobre, aluminio y acero a través de gestores autorizados", explicacion: "Los residuos metálicos generados (cobre, aluminio, acero) deben separarse adecuadamente y entregarse para su reciclaje a través de gestores autorizados, reduciendo el impacto ambiental de la actividad del taller." },
  { id: 801319, tema: "U13: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué obligación tiene el trabajador respecto al uso de los equipos de protección individual proporcionados por la empresa?", opciones: ["Utilizarlos correctamente conforme a las instrucciones recibidas y velar por su buen estado de conservación", "Puede decidir libremente no utilizarlos si lo considera innecesario", "Solo debe utilizarlos si un compañero se lo recuerda expresamente", "No tiene ninguna obligación relacionada con los EPI proporcionados"], correctaTexto: "Utilizarlos correctamente conforme a las instrucciones recibidas y velar por su buen estado de conservación", explicacion: "El trabajador tiene la obligación de utilizar correctamente los equipos de protección individual conforme a las instrucciones recibidas, así como de velar por su buen estado de conservación y uso adecuado." },
  { id: 801320, tema: "U13: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué finalidad tiene la vigilancia periódica de la salud de los trabajadores expuestos a riesgos en un taller de máquinas eléctricas?", opciones: ["Controlar el estado de salud de los trabajadores en relación con los riesgos derivados de su puesto de trabajo", "Sustituir completamente a las medidas preventivas técnicas del taller", "Es un trámite opcional sin ninguna relevancia para la seguridad laboral", "Solo se aplica a trabajadores mayores de 55 años"], correctaTexto: "Controlar el estado de salud de los trabajadores en relación con los riesgos derivados de su puesto de trabajo", explicacion: "La vigilancia periódica de la salud tiene como finalidad controlar el estado de salud de los trabajadores en relación con los riesgos específicos derivados de su puesto de trabajo, permitiendo detectar de forma precoz posibles afecciones." }
];

